    val HADITHS_500: List<HadithItem> = listOf(
HadithItem(1, "متفق عليه", "الإخلاص والنية", "1", "إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى، فمن كانت هجرته إلى الله ورسوله فهجرته إلى الله ورسوله، ومن كانت هجرته لدنيا يصيبها أو امرأة ينكحها فهجرته إلى ما هاجر إليه.", "Actions are judged by intentions, and every person will get what they intended.", "عن أمير المؤمنين عمر بن الخطاب رضي الله عنه"),
        HadithItem(2, "صحيح مسلم", "أركان الإسلام والإيمان", "8", "الإسلام أن تشهد أن لا إله إلا الله وأن محمداً رسول الله، وتقيم الصلاة، وتؤتي الزكاة، وتصوم رمضان، وتحج البيت إن استطعت إليه سبيلاً.", "Islam is to testify that there is no god but Allah and Muhammad is His Messenger...", "عن عمر بن الخطاب رضي الله عنه"),
        HadithItem(3, "متفق عليه", "بني الإسلام على خمس", "16", "بُني الإسلام على خمس: شهادة أن لا إله إلا الله وأن محمداً رسول الله، وإقام الصلاة، وإيتاء الزكاة، والحج، وصوم رمضان.", "Islam is built upon five pillars...", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(4, "صحيح مسلم", "حلاوة الإيمان", "43", "ثلاث من كن فيه وجد حلاوة الإيمان: أن يكون الله ورسوله أحب إليه مما سواهما، وأن يحب المرء لا يحبه إلا لله، وأن يكره أن يعود في الكفر كما يكره أن يقذف في النار.", "Three qualities, whoever possesses them will taste the sweetness of faith...", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(5, "متفق عليه", "مكفرات الذنوب", "268", "الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان، مكفرات ما بينهن إذا اجتنبت الكبائر.", "The five daily prayers, Friday to Friday, Ramadan to Ramadan expiate sins...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(6, "صحيح مسلم", "فضل الذكر والدعاء", "2691", "أحب الكلام إلى الله أربع: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، لا يضرك بأيهن بدأت.", "The most beloved words to Allah are four: SubhanAllah, Alhamdulillah, La ilaha illallah, Allahu Akbar.", "عن سمرة بن جندب رضي الله عنه"),
        HadithItem(7, "متفق عليه", "كلمتان خفيفتان", "6406", "كلمتان خفيفتان على اللسان، ثقيلتان في الميزان، حبيبتان إلى الرحمن: سبحان الله وبحمده، سبحان الله العظيم.", "Two words are light on the tongue, heavy on the scale...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(8, "صحيح مسلم", "الطهارة شطر الإيمان", "223", "الطهور شطر الإيمان، والحمد لله تملأ الميزان، وسبحان الله والحمد لله تملآن ما بين السماوات والأرض.", "Purity is half of faith, and Alhamdulillah fills the scale...", "عن أبي مالك الأشعري رضي الله عنه"),
        HadithItem(9, "متفق عليه", "حق المسلم على المسلم", "2162", "حق المسلم على المسلم خمس: رد السلام، وعيادة المريض، واتباع الجنائز، وإجابة الدعوة، وتشميت العاطس.", "The rights of a Muslim over another Muslim are five...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(10, "متفق عليه", "لا تؤذوا المسلمين", "10", "المسلم من سلم المسلمون من لسانه ويده، والمهاجر من هجر ما نهى الله عنه.", "A true Muslim is the one from whose tongue and hand other Muslims are safe.", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(11, "سنن الترمذي", "أكمل المؤمنين إيماناً", "1162", "أكمل المؤمنين إيماناً أحسنهم خُلُقاً، وخياركم خياركم لنسائهم.", "The most complete of believers in faith are those with the best character.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(12, "صحيح مسلم", "شعب الإيمان", "35", "الإيمان بضع وسبعون أو بضع وستون شعبة، فأفضلها قول لا إله إلا الله، وأدناها إماطة الأذى عن الطريق، والحياء شعبة من الإيمان.", "Faith has over seventy branches, the highest is saying La ilaha illallah...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(13, "متفق عليه", "من آمن بالله واليوم الآخر", "6018", "من كان يؤمن بالله واليوم الآخر فليقل خيراً أو ليصمت، ومن كان يؤمن بالله واليوم الآخر فليكرم جاره، ومن كان يؤمن بالله واليوم الآخر فليكرم ضيفه.", "Whoever believes in Allah and the Last Day should speak good or remain silent...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(14, "صحيح مسلم", "الدين النصيحة", "55", "الدين النصيحة. قلنا: لمن؟ قال: لله ولكتابه ولرسوله ولأئمة المسلمين وعامتهم.", "Religion is sincerity and good counsel...", "عن تميم الداري رضي الله عنه"),
        HadithItem(15, "سنن الترمذي", "حسن إسلام المرء", "2317", "من حسن إسلام المرء تركه ما لا يعنيه.", "Part of the perfection of a person's Islam is leaving that which does not concern him.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(16, "صحيح مسلم", "عجب لأمر المؤمن", "2999", "عجباً لأمر المؤمن إن أمره كله خير، وليس ذاك لأحد إلا للمؤمن؛ إن أصابته سراء شكر فكان خيراً له، وإن أصابته ضراء صبر فكان خيراً له.", "How wonderful is the affair of the believer, for all his affairs are good...", "عن صهيب الرومي رضي الله عنه"),
        HadithItem(17, "متفق عليه", "ذاق طعم الإيمان", "56", "ذاق طعم الإيمان من رضي بالله رباً، وبالإسلام ديناً، وبمحمد رسولاً.", "He has tasted the sweetness of faith who is pleased with Allah as his Lord...", "عن العباس بن عبد المطلب رضي الله عنه"),
        HadithItem(18, "صحيح البخاري", "الإيمان والعمل الصالح", "36", "سُئل النبي صلى الله عليه وسلم: أي الأعمال أفضل؟ قال: إيمان بالله ورسوله. قيل: ثم ماذا؟ قال: جهاد في سبيل الله. قيل: ثم ماذا؟ قال: حج مبرور.", "The Prophet was asked: Which deed is best? He said: Faith in Allah and His Messenger...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(19, "صحيح مسلم", "الصدق يهدي إلى البر", "2607", "عليكم بالصدق، فإن الصدق يهدي إلى البر، وإن البر يهدي إلى الجنة، وما يزال الرجل يصدق ويتحرى الصدق حتى يكتب عند الله صديقاً.", "Adhere to truthfulness, for truthfulness leads to righteousness...", "عن عبد الله بن مسعود رضي الله عنه"),
        HadithItem(20, "سنن الترمذي", "البر حسن الخلق", "1987", "البر حسن الخلق، والإثم ما حاك في صدرك وكرهت أن يطلع عليه الناس.", "Righteousness is good character, and sin is that which weaves in your chest...", "عن النواس بن سمعان رضي الله عنه"),
        HadithItem(21, "صحيح البخاري", "فضل القرآن الكريم", "5027", "خيركم من تعلم القرآن وعلمه.", "The best among you are those who learn the Quran and teach it.", "عن عثمان بن عفان رضي الله عنه"),
        HadithItem(22, "صحيح مسلم", "شفاعة القرآن", "804", "اقرؤوا القرآن فإنه يأتي يوم القيامة شفيعاً لأصحابه.", "Recite the Quran, for it will come on the Day of Resurrection as an intercessor...", "عن أبي أمامة الباهلي رضي الله عنه"),
        HadithItem(23, "صحيح مسلم", "نزول السكينة", "2699", "ما اجتمع قوم في بيت من بيوت الله يتلون كتاب الله ويتدارسونه بينهم إلا نزلت عليهم السكينة وحفتهم الملائكة.", "No group gathers in a house of Allah reciting the Quran...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(24, "متفق عليه", "الماهر بالقرآن", "798", "الماهر بالقرآن مع السفرة الكرام البررة، والذي يقرأ القرآن ويتعتع فيه وهو عليه شاق له أجران.", "The one who is skilled in Quran recitation will be with the noble angels...", "عن عائشة أم المؤمنين رضي الله عنها"),
        HadithItem(25, "سنن الترمذي", "الحسنة بعشر أمثالها", "2910", "من قرأ حرفاً من كتاب الله فله به حسنة، والحسنة بعشر أمثالها، لا أقول الم حرف، ولكن ألف حرف ولام حرف وميم حرف.", "Whoever recites a letter from the Book of Allah receives ten rewards...", "عن عبد الله بن مسعود رضي الله عنه"),
        HadithItem(26, "صحيح مسلم", "طلب العلم فريضة", "2699", "من سلك طريقاً يلتمس فيه علماً سهل الله له به طريقاً إلى الجنة.", "Whoever treads a path seeking knowledge, Allah makes easy for him a path to Paradise.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(27, "صحيح البخاري", "من يرد الله به خيراً", "71", "من يرد الله به خيراً يفقهه في الدين.", "Whomever Allah desires good for, He grants him deep understanding of the religion.", "عن معاوية بن أبي سفيان رضي الله عنه"),
        HadithItem(28, "سنن أبي داود", "فضل العلماء", "3641", "وإن العلماء ورثة الأنبياء، وإن الأنبياء لم يورثوا ديناراً ولا درهماً، وإنما ورثوا العلم، فمن أخذه أخذ بحظ وافر.", "Scholars are the inheritors of the Prophets...", "عن أبي الدرداء رضي الله عنه"),
        HadithItem(29, "صحيح مسلم", "العلم النافع بعد الموت", "1631", "إذا مات الإنسان انقطع عنه عمله إلا من ثلاثة: إلا من صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له.", "When a person dies, their deeds end except for three...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(30, "صحيح مسلم", "الدال على الخير", "1893", "من دل على خير فله مثل أجر فاعله.", "Whoever guides someone to goodness will have a reward like that of the doer.", "عن أبي مسعود الأنصاري رضي الله عنه"),
        HadithItem(31, "سنن النسائي", "فضل سورة البقرة وآل عمران", "805", "اقرؤوا الزهراوين: البقرة وسورة آل عمران، فإنهما تأتيان يوم القيامة كأنهما غمامتان تحاجان عن أصحابهما.", "Recite the two bright surahs: Al-Baqarah and Ali Imran...", "عن النواس بن سمعان رضي الله عنه"),
        HadithItem(32, "سنن الترمذي", "سورة تبارك المنجية", "2891", "إن سورة من القرآن ثلاثون آية شُفعت لرجل حتى غُفر له، وهي سورة تبارك الذي بيده الملك.", "A surah from the Quran containing thirty verses interceded for a man...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(33, "صحيح البخاري", "فضل قل هو الله أحد", "5013", "والذي نفسي بيده إنها لتعدل ثلث القرآن.", "By Him in Whose Hand is my soul, it (Surah Al-Ikhlas) is equivalent to one-third of the Quran.", "عن أبي سعيد الخدري رضي الله عنه"),
        HadithItem(34, "صحيح مسلم", "أعظم آية في كتاب الله", "810", "يا أبا المنذر، أتدري أي آية من كتاب الله معك أعظم؟ قلت: الله لا إله إلا هو الحي القيوم، فضرب في صدري وقال: والله ليهنك العلم أبا المنذر.", "Do you know which verse of Allah's Book is greatest? Ayat al-Kursi...", "عن أبي بن كعب رضي الله عنه"),
        HadithItem(35, "صحيح مسلم", "آيتان من آخر سورة البقرة", "807", "من قرأ بالآيتين من آخر سورة البقرة في ليلة كفتاه.", "Whoever recites the last two verses of Surah Al-Baqarah at night, they suffice him.", "عن أبي مسعود البدري رضي الله عنه"),
        HadithItem(36, "سنن أبي داود", "تعاهدوا القرآن", "4889", "تعاهدوا هذا القرآن، فوالذي نفس محمد بيده لهو أشد تفلتاً من الإبل في عقلها.", "Keep reviewing the Quran, for it escapes faster than camels from their bonds.", "عن عبد الله بن مسعود رضي الله عنه"),
        HadithItem(37, "صحيح البخاري", "يقال لصاحب القرآن اقرأ وارتق", "5052", "يقال لصاحب القرآن: اقرأ وارتق ورتل كما كنت ترتل في الدنيا، فإن منزلتك عند آخر آية تقرؤها.", "It will be said to the companion of the Quran: Recite and ascend...", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(38, "صحيح مسلم", "فضل تلاوة القرآن في البيوت", "780", "لا تجعلوا بيوتكم مقابر، إن الشيطان ينفر من البيت الذي تقرأ فيه سورة البقرة.", "Do not make your houses graveyards; Satan flees from the house in which Surah Al-Baqarah is recited.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(39, "سنن ابن ماجه", "إن لله أهلين من الناس", "215", "إن لله أهلين من الناس. قالوا: يا رسول الله من هم؟ قال: هم أهل القرآن أهل الله وخاصته.", "Allah has His people among mankind: the people of the Quran...", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(40, "مسند أحمد", "فضل طلب العلم", "12132", "من خرج في طلب العلم فهو في سبيل الله حتى يرجع.", "Whoever goes out seeking knowledge is in the cause of Allah until he returns.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(41, "سنن الترمذي", "إنما بعثت لأتمم مكارم الأخلاق", "2003", "إن من أحبكم إلي وأقربكم مني مجلساً يوم القيامة أحاسنكم أخلاقاً.", "The most beloved to me and closest to me on Judgment Day are those with best character.", "عن جابر بن عبد الله رضي الله عنهما"),
        HadithItem(42, "سنن الترمذي", "أثقل شيء في الميزان", "2002", "ما شيء أثقل في ميزان المؤمن يوم القيامة من خلق حسن، وإن الله ليبغض الفاحش البذيء.", "Nothing is heavier on the believer's scale than good character.", "عن أبي الدرداء رضي الله عنه"),
        HadithItem(43, "سنن الترمذي", "تبسمك في وجه أخيك", "1956", "تبسمك في وجه أخيك لك صدقة، وأمرك بالمعروف ونهيك عن المنكر صدقة.", "Your smile for your brother is a charity...", "عن أبي ذر الغفاري رضي الله عنه"),
        HadithItem(44, "متفق عليه", "محبة الخير للغير", "13", "لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه.", "None of you truly believes until he loves for his brother what he loves for himself.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(45, "صحيح مسلم", "التواضع يرفع صاحبه", "2588", "ما نقصت صدقة من مال، وما زاد الله عبداً بعفو إلا عزاً، وما تواضع أحد لله إلا رفعه الله.", "Charity does not decrease wealth, and Allah elevates the humble.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(46, "متفق عليه", "الرفق في الأمور كلها", "2593", "إن الرفق لا يكون في شيء إلا زانه، ولا ينزع من شيء إلا شانه.", "Gentleness is not in anything except that it beautifies it...", "عن عائشة أم المؤمنين رضي الله عنها"),
        HadithItem(47, "متفق عليه", "النهي عن الغضب", "6114", "ليس الشديد بالصُّرَعَة، إنما الشديد الذي يملك نفسه عند الغضب.", "The strong person is not the good wrestler, but the one who controls himself in anger.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(48, "صحيح البخاري", "وصية بعدم الغضب", "6116", "أن رجلاً قال للنبي صلى الله عليه وسلم: أوصني. قال: لا تغضب. فردد مراراً، قال: لا تغضب.", "A man asked the Prophet for advice; he replied: Do not become angry.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(49, "متفق عليه", "إكرام الضيف والجار", "6018", "من كان تؤمن بالله واليوم الآخر فليكرم ضيفه، ومن كان يؤمن بالله واليوم الآخر فليصل رحمه.", "Whoever believes in Allah and the Last Day should honor his guest and ties of kinship.", "عن أبي شريح الخزاعي رضي الله عنه"),
        HadithItem(50, "صحيح مسلم", "من نفَّس عن مؤمن كربة", "2699", "من نفس عن مؤمن كربة من كرب الدنيا نفس الله عنه كربة من كرب يوم القيامة، ومن يسر على معسر يسر الله عليه في الدنيا والآخرة.", "Whoever relieves a believer's hardship in this world, Allah relieves his hardship on Judgment Day.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(51, "سنن أبي داود", "خياركم خياركم لأهله", "4682", "خيركم خيركم لأهله، وأنا خيركم لأهلي.", "The best of you are those who are best to their families...", "عن عائشة أم المؤمنين رضي الله عنها"),
        HadithItem(52, "صحيح مسلم", "أحب الأعمال إلى الله أدومها", "783", "أحب الأعمال إلى الله أدومها وإن قل.", "The most beloved deeds to Allah are those done consistently, even if small.", "عن عائشة أم المؤمنين رضي الله عنها"),
        HadithItem(53, "سنن الترمذي", "اتق الله حيثما كنت", "1987", "اتق الله حيثما كنت، وأتبع السيئة الحسنة تمحها، وخالق الناس بخلق حسن.", "Fear Allah wherever you are, follow a bad deed with a good one to wipe it out...", "عن أبي ذر ومعاذ بن جبل رضي الله عنهما"),
        HadithItem(54, "صحيح البخاري", "السعي على الأرملة والمسكين", "5353", "الساعي على الأرملة والمسكين كالمجاهد في سبيل الله، أو القائم الليل الصائم النهار.", "One who strives for widows and the poor is like a fighter in Allah's cause...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(55, "متفق عليه", "الراحمون يرحمهم الرحمن", "1924", "الراحمون يرحمهم الرحمن، ارحموا من في الأرض يرحمكم من في السماء.", "The merciful will be shown mercy by the Most Merciful. Show mercy to those on earth...", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(56, "صحيح مسلم", "من لا يَرْحَم لا يُرْحَم", "2318", "من لا يرحم الناس لا يرحمه الله.", "Whoever does not show mercy to people, Allah will not show mercy to him.", "عن جرير بن عبد الله رضي الله عنه"),
        HadithItem(57, "صحيح البخاري", "تقبيل الأطفال والرحمة", "5997", "أو أملك لك أن نزع الله من قلبك الرحمة؟! ", "Can I put mercy back in your heart if Allah has taken it out?!", "عن عائشة أم المؤمنين رضي الله عنها"),
        HadithItem(58, "متفق عليه", "الحياء خير كله", "6117", "الحياء لا يأتي إلا بخير.", "Modesty brings nothing but goodness.", "عن عمران بن حصين رضي الله عنه"),
        HadithItem(59, "صحيح مسلم", "الكلمة الطيبة صدقة", "1009", "والكلمة الطيبة صدقة، وبكل خطوة تمشيها إلى الصلاة صدقة.", "A good word is charity, and every step taken towards prayer is charity.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(60, "سنن الترمذي", "إن الله جميل يحب الجمال", "1999", "إن الله جميل يحب الجمال، الكبر بَطَر الحق وغَمْط الناس.", "Allah is Beautiful and loves beauty. Arrogance is refusing truth and despising people.", "عن عبد الله بن مسعود رضي الله عنه"),
        HadithItem(61, "صحيح مسلم", "أول ما يحاسب عليه العبد", "2835", "إن أول ما يحاسب به العبد يوم القيامة من عمله صلاته، فإن صلحت فقد أفلح وأنجح، وإن فسدت فقد خاب وخسر.", "The first thing a servant is held accountable for on Judgment Day is prayer...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(62, "صحيح البخاري", "فضل صلاة الجماعة", "645", "صلاة الجماعة تفضل صلاة الفذ بسبع وعشرين درجة.", "Prayer in congregation is twenty-seven times superior to individual prayer.", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(63, "صحيح مسلم", "فضل العشاء والصبح في جماعة", "656", "من صلى العشاء في جماعة فكأنما قام نصف الليل، ومن صلى الصبح في جماعة فكأنما صلى الليل كله.", "Whoever prays Isha in congregation, it is as if he prayed half the night...", "عن عثمان بن عفان رضي الله عنه"),
        HadithItem(64, "متفق عليه", "من صلى البردين دخل الجنة", "574", "من صلى البردين دخل الجنة.", "Whoever prays the two cool prayers (Fajr and Asr) will enter Paradise.", "عن أبي موسى الأشعري رضي الله عنه"),
        HadithItem(65, "صحيح مسلم", "أقرب ما يكون العبد من ربه", "482", "أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء.", "The closest a servant comes to his Lord is while in prostration, so increase supplication.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(66, "سنن الترمذي", "صلاة الضحى والأوابين", "473", "من صلى الفجر في جماعة ثم قعد يذكر الله حتى تطلع الشمس ثم صلى ركعتين كانت له كأجر حجة وعمرة تامّة تامّة تامّة.", "Whoever prays Fajr in congregation and then sits remembering Allah until sunrise...", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(67, "صحيح مسلم", "السنن الرواجب اثنتا عشرة ركعة", "728", "ما من عبد مسلم يصلي لله كل يوم ثنتي عشرة ركعة تطوعاً غير فريضة إلا بني الله له بيتاً في الجنة.", "Any Muslim servant who prays twelve voluntary rak'ahs every day for Allah...", "عن أم حبيبة رضي الله عنها"),
        HadithItem(68, "صحيح البخاري", "ركعتا الفجر خير من الدنيا", "1162", "ركعتا الفجر خير من الدنيا وما فيها.", "The two rak'ahs of Fajr are better than this world and everything in it.", "عن عائشة أم المؤمنين رضي الله عنها"),
        HadithItem(69, "صحيح مسلم", "وجُعلت لي الأرض مسجداً وطهوراً", "521", "وجُعلت لي الأرض مسجداً وطهوراً، فأيما رجل من أمتي أدركته الصلاة فليصلِّ.", "The earth has been made a place of prayer and pure for me...", "عن جابر بن عبد الله رضي الله عنهما"),
        HadithItem(70, "متفق عليه", "إسباغ الوضوء في المكاره", "251", "ألا أدلكم على ما يمحو الله به الخطايا ويرفع به الدرجات؟ إسباغ الوضوء على المكاره، وكثرة الخطى إلى المساجد، وانتظار الصلاة بعد الصلاة.", "Shall I not guide you to that by which Allah wipes away sins and raises status?...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(71, "صحيح البخاري", "فضل الأذان والمؤذنين", "608", "المؤذنون أطول الناس أعناقاً يوم القيامة.", "The muezzins will have the longest necks on the Day of Resurrection.", "عن معاوية بن أبي سفيان رضي الله عنه"),
        HadithItem(72, "صحيح مسلم", "إجابة الأذان بالدعاء", "384", "إذا سمعتم المؤذن فقولوا مثل ما يقول، ثم صلوا عليّ، ثم سلوا الله لي الوسيلة.", "When you hear the caller to prayer, repeat what he says, then send blessings upon me...", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(73, "سنن أبي داود", "الدعاء بين الأذان والإقامة", "521", "الدعاء لا يرد بين الأذان والإقامة.", "Supplication made between the Adhan and Iqamah is not rejected.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(74, "صحيح مسلم", "الجمعة إلى الجمعة كفارة", "233", "الصلوات الخمس والجمعة إلى الجمعة مكفرات لما بينهن ما لم تغش الكبائر.", "The five daily prayers and Friday to Friday are expiations for what occurs between them...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(75, "صحيح البخاري", "فضل الغسل يوم الجمعة والتبكير", "883", "من اغتسل يوم الجمعة غسل الجنابة ثم راح فكأنما قرب بدنة...", "Whoever takes a bath on Friday and goes early to the mosque, it is as if he sacrificed a camel...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(76, "صحيح مسلم", "ساعة الإجابة يوم الجمعة", "852", "إن في الجمعة لساعة لا يوافقها عبد مسلم وهو قائم يصلي يسأل الله شيئاً إلا أعطاه إياه.", "Indeed on Friday there is an hour in which no Muslim servant asks Allah for good except He gives it.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(77, "متفق عليه", "فضل صلاة الليل والوتر", "1122", "أفضل الصيام بعد رمضان شهر الله المحرم، وأفضل الصلاة بعد الفريضة صلاة الليل.", "The best prayer after obligatory prayer is the night prayer (Tahajjud).", "عن أبي هريرة رضي الله عنه"),
        HadithItem(78, "صحيح البخاري", "اجعلوا آخر صلاتكم بالليل وتراً", "998", "اجعلوا آخر صلاتكم بالليل وتراً.", "Make the last of your prayer at night Witr.", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(79, "صحيح مسلم", "ينزل ربنا كل ليلة", "758", "ينزل ربنا تبارك وتعالى كل ليلة إلى السماء الدنيا حين يبقى ثلث الليل الآخر فيقول: من يدعوني فأستجيب له؟ من يسألني فأعطيه؟ من يستغفرني فأغفر له؟", "Our Lord descends every night to the lowest heaven during the last third of the night...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(80, "سنن الترمذي", "استقامة الصلاة والخشوع", "2616", "استقيموا ولن تحصوا، واعلموا أن خير أعمالكم الصلاة، ولا يحافظ على الوضوء إلا مؤمن.", "Be steadfast; know that the best of your deeds is prayer...", "عن ثوبان مولى النبي رضي الله عنه"),
        HadithItem(81, "متفق عليه", "بر الوالدين وأحق الناس بالمصاحبة", "5971", "جاء رجل إلى رسول الله فقال: يا رسول الله، من أحق الناس بحسن صحابتي؟ قال: أمك. قال: ثم من؟ قال: ثم أمك. قال: ثم من؟ قال: ثم أمك. قال: ثم من؟ قال: ثم أبوك.", "A man asked: Who is most deserving of my good companionship? He replied: Your mother, your mother, your mother, then your father.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(82, "صحيح مسلم", "رغم أنف من أدرك والديه", "2551", "رغم أنفه، ثم رغم أنفه، ثم رغم أنفه. قيل: من يا رسول الله؟ قال: من أدرك والديه عند الكبر أحدهما أو كلاهما ثم لم يدخل الجنة.", "May his nose be rubbed in dust, who sees his parents reach old age and does not enter Paradise...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(83, "متفق عليه", "صلة الرحم تبسط الرزق وتنسأ الأثر", "2557", "من أحب أن يبسط له في رزقه، وينسأ له في أثره، فليصل رحمه.", "Whoever wishes for his provision to be expanded and his lifespan extended, let him maintain ties of kinship.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(84, "صحيح البخاري", "الرحم معلقة بالعرش", "5989", "الرحم معلقة بالعرش تقول: من وصلني وصله الله، ومن قطعني قطعه الله.", "Kinship is suspended from the Throne, saying: Whoever maintains me, Allah maintains him...", "عن عائشة أم المؤمنين رضي الله عنها"),
        HadithItem(85, "صحيح مسلم", "ليس الواصل بالمكافئ", "5991", "ليس الواصل بالمكافئ، ولكن الواصل الذي إذا قطعت رحمه وصلها.", "The one who maintains ties of kinship is not the one who merely reciprocates...", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(86, "متفق عليه", "إكرام الجار وحفظ حقّه", "6014", "ما زال جبريل يوصيني بالجار حتى ظننت أنه سيورثه.", "Gabriel kept advising me concerning the neighbor until I thought he would make him an heir.", "عن ابن عمر وعائشة رضي الله عنهم"),
        HadithItem(87, "صحيح مسلم", "لا يدخل الجنة من لا يأمن جاره بوائقه", "46", "لا يدخل الجنة من لا يأمن جاره بوائقه.", "He will not enter Paradise whose neighbor is not safe from his harm.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(88, "سنن الترمذي", "إذا طبخت مرقة فأكثر ماءها", "2488", "إذا طبخت مرقة فأكثر ماءها وتعاهد جيرانك.", "When you cook broth, increase its water and share with your neighbors.", "عن أبي ذر الغفاري رضي الله عنه"),
        HadithItem(89, "متفق عليه", "الصدقة تطفئ الخطيئة", "1405", "الصدقة تطفئ الخطيئة كما يطفئ الماء النار.", "Charity extinguishes sin just as water extinguishes fire.", "عن معاذ بن جبل رضي الله عنه"),
        HadithItem(90, "صحيح مسلم", "اليد العليا خير من اليد السفلى", "1042", "اليد العليا خير من اليد السفلى، وابدأ بمن تعول، وخير الصدقة عن ظهر غنى.", "The upper hand is better than the lower hand, and begin with those under your care.", "عن حكيم بن حزام رضي الله عنه"),
        HadithItem(91, "صحيح البخاري", "كافل اليتيم في الجنة", "5304", "أنا وكافل اليتيم في الجنة هكذا، وأشار بالسبابة والوسطى وفرج بينهما شيئاً.", "I and the guardian of an orphan will be in Paradise like these two (fingers)...", "عن سهل بن سعد رضي الله عنه"),
        HadithItem(92, "صحيح مسلم", "كل معروف صدقة", "1005", "كل معروف صدقة.", "Every good deed is a charity.", "عن جابر بن عبد الله رضي الله عنهما"),
        HadithItem(93, "متفق عليه", "على كل مسلم صدقة", "1445", "على كل مسلم صدقة. قالوا: فإن لم يجد؟ قال: يعمل بيده فينفع نفسه ويتصدق...", "Charity is incumbent upon every Muslim...", "عن أبي موسى الأشعري رضي الله عنه"),
        HadithItem(94, "صحيح البخاري", "أنفق ينفق عليك", "5352", "قال الله تبارك وتعالى: يا ابن آدم أنفق أُنفق عليك.", "Allah Almighty said: O son of Adam, spend and I shall spend on you.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(95, "صحيح مسلم", "ما من يوم يصبح العباد فيه إلا ملكان ينزلان", "1010", "ما من يوم يصبح العباد فيه إلا ملكان ينزلان فيقول أحدهما: اللهم أعطِ منفقاً خلفاً، ويقول الآخر: اللهم أعطِ ممسكاً تلفاً.", "Every day two angels descend, one says: O Allah give compensation to the spender...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(96, "سنن الترمذي", "اتقوا النار ولو بشق تمرة", "2415", "اتقوا النار ولو بشق تمرة، فمن لم يجد فبكلمة طيبة.", "Guard yourselves against the Fire even with half a date, and if not found, then with a good word.", "عن عدي بن حاتم رضي الله عنه"),
        HadithItem(97, "صحيح مسلم", "سبعة يظلهم الله في ظله", "1031", "سبعة يظلهم الله في ظله يوم لا ظل إلا ظله: إمام عادل، وشاب نشأ في عبادة الله، ورجل قلبه معلق بالمساجد...", "Seven whom Allah will shade in His shade on the Day when there is no shade but His...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(98, "صحيح البخاري", "فضل إطعام الطعام", "12", "سُئل النبي: أي الإسلام خير؟ قال: تطعم الطعام، وتقرأ السلام على من عرفت ومن لم تعرف.", "Which Islam is best? He said: Feeding people food, and spreading peace to those you know and don't know.", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(99, "صحيح مسلم", "في كل كبد رطبة أجر", "2244", "بينما رجل يمشي بطريق اشتد عليه العطش فنزل بئراً فشرب ثم خرج فإذا كلب يلهث يأكل الثرى من العطش... فسقاه فغفر الله له.", "While a man was walking he became very thirsty... He gave water to a thirsty dog, so Allah forgiven him.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(100, "متفق عليه", "لا تحقرن من المعروف شيئاً", "144", "لا تحقرن من المعروف شيئاً ولو أن تلقى أخاك بوجْهٍ طَلْقٍ.", "Do not belittle any good deed, even meeting your brother with a cheerful face.", "عن أبي ذر الغفاري رضي الله عنه"),
        HadithItem(101, "صحيح مسلم", "التوكل على الله حق توكله", "2164", "لو أنكم تتوكلون على الله حق توكله لرزقكم كما يرُزق الطير؛ تغدو خماصاً وتروح بطاناً.", "If you were to rely upon Allah with true reliance, He would provide for you as He provides for birds...", "عن عمر بن الخطاب رضي الله عنه"),
        HadithItem(102, "صحيح البخاري", "عظم أجر الصبر عند الصدمة الأولى", "1283", "إنما الصبر عند الصدمة الأولى.", "True patience is only at the first stroke of a calamity.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(103, "صحيح مسلم", "ما يُصيب المسلم من نصب ولا وصب", "2573", "ما يصيب المسلم من نصب ولا وصب ولا هم ولا حزن ولا أذى ولا غم، حتى شوكة يشاكها إلا كفر الله بها من خطاياه.", "No fatigue, illness, anxiety, sorrow, harm, or distress befalls a Muslim except that Allah expiates sins thereby.", "عن أبي سعيد وأبي هريرة رضي الله عنهما"),
        HadithItem(104, "صحيح البخاري", "من يرد الله به خيراً يصب منه", "5645", "من يرد الله به خيراً يُصِبْ منه.", "Whomever Allah intends good for, He subjects him to trials.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(105, "سنن الترمذي", "عظم الجزاء مع عظم البلاء", "2396", "إن عظم الجزاء مع عظم البلاء، وإن الله إذا أحب قوماً ابتلاهم، فمن رضي فله الرضا، ومن سخط فله السخط.", "Great reward comes with great trial. When Allah loves a people, He tests them...", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(106, "صحيح مسلم", "احفظ الله يحفظك", "2516", "احفظ الله يحفظك، احفظ الله تجده تجاهك، إذا سألت فاسأل الله، وإذا استعنت فاستعن بالله.", "Be mindful of Allah and He will protect you; be mindful of Allah and you will find Him in front of you...", "عن عبد الله بن عباس رضي الله عنهما"),
        HadithItem(107, "صحيح البخاري", "اعقلها وتوكل", "2517", "قال رجل: يا رسول الله أرسل ناقتي وأتوكل؟ قال: اعقلها وتوكل.", "A man asked: Should I tie my camel and trust in Allah? He said: Tie her and trust in Allah.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(108, "سنن الترمذي", "النصر مع الصبر والفرج مع الكرب", "2516", "واعلم أن النصر مع الصبر، وأن الفرج مع الكرب، وأن مع العسر يسراً.", "Know that victory comes with patience, relief with distress, and ease with hardship.", "عن عبد الله بن عباس رضي الله عنهما"),
        HadithItem(109, "صحيح مسلم", "أشد الناس بلاء الأنبيـاء", "2398", "سئل النبي: أي الناس أشد بلاء؟ قال: الأنبياء، ثم الأمثل فالأمثل، يُبتلى الرجل على حسب دينه.", "Which people are most severely tested? The Prophets, then the next best...", "عن سعد بن أبي وقاص رضي الله عنه"),
        HadithItem(110, "متفق عليه", "الصبر ضياء", "223", "والصبر ضياء، والقرآن حجة لك أو عليك.", "Patience is a shining light, and the Quran is a proof for you or against you.", "عن أبي مالك الأشعري رضي الله عنه"),
        HadithItem(111, "صحيح البخاري", "ما أعطي أحد عطاء خيراً وأوسع من الصبر", "1469", "وما أُعطي أحد عطاء خيراً وأوسع من الصبر.", "No one has been given a gift better and more comprehensive than patience.", "عن أبي سعيد الخدري رضي الله عنه"),
        HadithItem(112, "صحيح مسلم", "أمر المؤمن كله خير", "2999", "إن أصابته سراء شكر فكان خيراً له، وإن أصابته ضراء صبر فكان خيراً له.", "If prosperity touches him he is thankful and it is good for him; if adversity touches him he is patient...", "عن صهيب بن سنان رضي الله عنه"),
        HadithItem(113, "سنن الترمذي", "لا يزال البلاء بالمؤمن", "2399", "لا يزال البلاء بالمؤمن والمؤمنة في نفسه وولده وماله حتى يلقى الله وما عليه خطيئة.", "Trials will continue to befall believing men and women in themselves, children, and wealth until they meet Allah sinless.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(114, "متفق عليه", "المؤمن القوي خير وأحب إلى الله", "2664", "المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف، وفي كل خير، احرص على ما ينفعك واستعن بالله ولا تعجز.", "The strong believer is better and more beloved to Allah than the weak believer...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(115, "صحيح مسلم", "ولا تقل لو أني فعلت كان كذا وكذا", "2664", "وإن أصابك شيء فلا تقل لو أني فعلت كان كذا وكذا، ولكن قل: قدر الله وما شاء فعل؛ فإن لو تفتح عمل الشيطان.", "If something befalls you, do not say 'if only I had done so-and-so', but say: Allah decreed and willed...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(116, "صحيح البخاري", "مثل المؤمن مثل الخامة من الزرع", "5644", "مثل المؤمن كمثل الخامة من الزرع تفيئها الريح صرعة وتعدلها أخرى...", "The parable of the believer is that of a fresh tender plant bent by the wind...", "عن كعب بن مالك رضي الله عنه"),
        HadithItem(117, "صحيح مسلم", "من مات له ثلاثة من الولد فاحتسبهم", "2632", "ما من مسلمين يموت لهما ثلاثة من الولد لم يبلغوا الحنث إلا أدخلهما الله الجنة بفضل رحمته إياهم.", "No Muslims lose three children before age of puberty except Allah enters them into Paradise...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(118, "سنن الترمذي", "بيت الحمد لمن صبر واحتسب ولده", "1021", "إذا مات ولد العبد قال الله لملائكته: قبضتم ولد عبدي؟... ماذا قال عبدي؟ قالوا: حمدك واسترجع. فيقول: ابنوا لعبدي بيتاً في الجنة وسموه بيت الحمد.", "When a servant's child dies, Allah says: Build my servant a house in Paradise and name it House of Praise.", "عن أبي موسى الأشعري رضي الله عنه"),
        HadithItem(119, "صحيح البخاري", "من أذهبت حبيبتيه فصبر", "5653", "إن الله قال: إذا ابتليت عبدي بحبيبتيه (عينيه) فصبر عوضته منهما الجنة.", "Allah said: If I test my servant with the loss of his two beloved eyes and he is patient, I reward him Paradise.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(120, "صحيح مسلم", "الصبر عند فقد الأحبة", "923", "إن الله لا يرضى لعبده المؤمن ثواباً دون الجنة إذا قبض صفيّه من أهل الدنيا ثم احتسبه.", "Allah is not pleased with any reward less than Paradise for His believing servant when He takes his beloved...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(121, "صحيح مسلم", "أفضل الذكر لا إله إلا الله", "2691", "أفضل الذكر لا إله إلا الله، وأفضل الدعاء الحمد لله.", "The best remembrance is La ilaha illallah, and the best supplication is Alhamdulillah.", "عن جابر بن عبد الله رضي الله عنهما"),
        HadithItem(122, "متفق عليه", "مثل الذي يذكر ربه والذي لا يذكر ربه", "6407", "مثل الذي يذكر ربه والذي لا يذكر ربه مثل الحي والميت.", "The parable of the one who remembers his Lord and the one who does not is like the living and the dead.", "عن أبي موسى الأشعري رضي الله عنه"),
        HadithItem(123, "صحيح مسلم", "سبحان الله وبحمده مائة مرة", "2692", "من قال حين يصبح وحين يمسي: سبحان الله وبحمده مائة مرة، لم يأت أحد يوم القيامة بأفضل مما جاء به إلا أحد قال مثل ما قال أو زاد عليه.", "Whoever says in the morning and evening 'SubhanAllah wa bihamdihi' 100 times...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(124, "صحيح البخاري", "سيد الاستغفار", "6306", "سيد الاستغفار أن تقول: اللهم أنت ربي لا إله إلا أنت، خلقتني وأنا عبدك، وأنا على عهدك ووعدك ما استطعت...", "The chief form of seeking forgiveness is to say: O Allah, You are my Lord...", "عن شداد بن أوس رضي الله عنه"),
        HadithItem(125, "صحيح مسلم", "لا حول ولا قوة إلا بالله كنز من كنوز الجنة", "2704", "يا عبد الله بن قيس، ألا أدلك على كنز من كنوز الجنة؟ قلت: بلى يا رسول الله. قال: لا حول ولا قوة إلا بالله.", "Shall I not guide you to a treasure from the treasures of Paradise? Say: La hawla wa la quwwata illa billah.", "عن أبي موسى الأشعري رضي الله عنه"),
        HadithItem(126, "سنن الترمذي", "الدعاء هو العبادة", "2969", "الدعاء هو العبادة، ثم قرأ: وقال ربكم ادعوني أستجب لكم.", "Supplication is worship itself.", "عن النعمان بن بشير رضي الله عنه"),
        HadithItem(127, "صحيح مسلم", "يستجاب لأحدكم ما لم يعجل", "2735", "يستجاب لأحدكم ما لم يعجل، يقول: دعوت فلم يستجب لي.", "The supplication of any of you is answered as long as he does not show impatience saying: I prayed and was not answered.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(128, "سنن الترمذي", "من لم يسأل الله يغضب عليه", "3373", "من لم يسأل الله يغضب عليه.", "Whoever does not ask Allah, He becomes angry with him.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(129, "صحيح مسلم", "دعوة المرء المسلم لأخيه بظهر الغيب", "2732", "دعوة المرء المسلم لأخيه بظهر الغيب مستجابة، عند رأسه ملك موكل كلما دعا لأخيه بخير قال الملك الموكل به: آمين ولك بمثل.", "The supplication of a Muslim for his brother in his absence is answered...", "عن أبي الدرداء رضي الله عنه"),
        HadithItem(130, "سنن أبي داود", "ثلاث دعوات مستجابات", "1536", "ثلاث دعوات مستجابات لا شك فيهن: دعوة المظلوم، ودعوة المسافر، ودعوة الوالد على ولده.", "Three supplications are answered without doubt: the prayer of the wronged, the traveler, and the parent.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(131, "صحيح البخاري", "فضل التسبيح بعد الصلاة", "843", "تسبحون وتحمدون وتكبرون خلف كل صلاة ثلاثاً وثلاثين.", "Recite SubhanAllah, Alhamdulillah, and Allahu Akbar 33 times after every prayer.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(132, "صحيح مسلم", "تمام المائة بعد الصلاة", "597", "من سبّح الله في دبر كل صلاة ثلاثاً وثلاثين، وحمد الله ثلاثاً وثلاثين، وكبّر الله ثلاثاً وثلاثين... وختم بالمائة غفرت خطاياه وإن كانت مثل زبد البحر.", "Whoever glorifies Allah after every prayer 33 times... and completes 100 with La ilaha illallah, his sins are forgiven...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(133, "سنن الترمذي", "فضل الصلاة على النبي", "2457", "من صلى عليّ صلاة صلى الله عليه بها عشراً.", "Whoever sends blessings upon me once, Allah sends blessings upon him ten times.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(134, "صحيح مسلم", "أولى الناس بي يوم القيامة أكثرهم علي صلاة", "2458", "إن أولى الناس بي يوم القيامة أكثرهم عليّ صلاة.", "The closest people to me on the Day of Resurrection are those who sent the most blessings upon me.", "عن عبد الله بن مسعود رضي الله عنه"),
        HadithItem(135, "صحيح البخاري", "دعاء الخروج من المنزل", "5095", "إذا خرج الرجل من بيته فقال: بسم الله توكلت على الله لا حول ولا قوة إلا بالله، يقال له: هديت وكفيت ووقيت.", "When a man leaves his house and says 'In the name of Allah, I trust in Allah...', it is said to him: You are guided and protected.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(136, "صحيح مسلم", "دعاء أرق الليل والفزع", "2708", "أعوذ بكلمات الله التامات من غضبه وعقابه وشر عباده ومن همزات الشياطين وأن يحضرون.", "I seek refuge in the perfect words of Allah from His anger and punishment...", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(137, "سنن أبي داود", "بسم الله الذي لا يضر مع اسمه شيء", "5088", "ما من عبد يقول في صباح كل يوم ومساء كل ليلة: بسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات لم يضره شيء.", "No servant says three times in morning and evening 'In the name of Allah with Whose name nothing harms...' and is harmed.", "عن عثمان بن عفان رضي الله عنه"),
        HadithItem(138, "صحيح مسلم", "أعوذ بكلمات الله التامات من شر ما خلق", "2708", "من نزل منزلاً ثم قال: أعوذ بكلمات الله التامات من شر ما خلق لم يضره شيء حتى يرتحل من منزله ذلك.", "Whoever stops at a place and says 'I seek refuge in Allah's perfect words from the evil of what He created' nothing will harm him.", "عن خولة بنت حكيم رضي الله عنها"),
        HadithItem(139, "صحيح البخاري", "دعاء الكرب والهم", "6345", "لا إله إلا الله العظيم الحليم، لا إله إلا الله رب العرش العظيم، لا إله إلا الله رب السماوات ورب الأرض ورب العرش الكريم.", "There is no god but Allah, the Tremendous, the Forbearing...", "عن عبد الله بن عباس رضي الله عنهما"),
        HadithItem(140, "سنن أبي داود", "دعوة ذي النون في بطن الحوت", "1493", "دعوة ذي النون إذ دعا وهو في بطن الحوت: لا إله إلا أنت سبحانك إني كنت من الظالمين؛ لم يدعُ بها رجل مسلم في شيء قط إلا استجاب الله له.", "The supplication of Yunus in the belly of the whale: There is no god but You, Exalted are You, indeed I was of the wrongdoers...", "عن سعد بن أبي وقاص رضي الله عنه"),
        HadithItem(141, "صحيح مسلم", "من غشنا فليس منا", "101", "من حمل علينا السلاح فليس منا، ومن غشنا فليس منا.", "Whoever bears arms against us is not of us, and whoever deceives us is not of us.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(142, "صحيح البخاري", "رحم الله رجلاً سمحاً إذا باع وإذا اشترى", "2076", "رحم الله رجلاً سمحاً إذا باع، وإذا اشترى، وإذا اقتضى.", "May Allah have mercy on a person who is lenient when selling, buying, and demanding back money.", "عن جابر بن عبد الله رضي الله عنهما"),
        HadithItem(143, "صحيح مسلم", "البيعان بالخيار ما لم يتفرقا", "1532", "البيعان بالخيار ما لم يتفرقا، فإن صدقا وبيّنا بورك لهما في بيعهما، وإن كتما وكذبا مُحقت بركة بيعهما.", "The buyer and seller have the option to cancel until they part; if they are truthful and transparent, blessed is their sale.", "عن حكيم بن حزام رضي الله عنه"),
        HadithItem(144, "سنن الترمذي", "التبيين والصدق في البيع", "1209", "التاجر الصدوق الأمين مع النبيين والصديقين والشهداء.", "The truthful and trustworthy merchant will be with the Prophets, the truthful, and the martyrs.", "عن أبي سعيد الخدري رضي الله عنه"),
        HadithItem(145, "صحيح البخاري", "أداء الأمانات إلى أهلها", "2257", "أدِّ الأمانة إلى من ائتمنك، ولا تخن من خانك.", "Fulfill the trust to him who entrusted you, and do not betray him who betrayed you.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(146, "صحيح مسلم", "مطل الغني ظلم", "1564", "مَطْلُ الغنيِّ ظُلْمٌ، وإذا أُتْبِعَ أحدُكم على مَلِيءٍ فَلْيَتْبَعْ.", "Delay in payment by a wealthy person is injustice...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(147, "صحيح البخاري", "من أخذ أموال الناس يريد أداءها", "2387", "من أخذ أموال الناس يريد أداءها أدى الله عنه، ومن أخذ يريد إتلافها أتلفه الله.", "Whoever takes people's wealth intending to repay it, Allah will settle it for him...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(148, "صحيح مسلم", "إعطاء الأجير أجره قبل أن يجف عرقه", "2287", "أعطوا الأجير أجره قبل أن يجف عرقه.", "Give the hired worker his wages before his sweat dries.", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(149, "صحيح البخاري", "الكسب الحلال والطيب", "2072", "ما أكل أحد طعاماً قط خيراً من أن يأكل من عمل يده، وإن نبي الله داود عليه السلام كان يأكل من عمل يده.", "No one has ever eaten better food than that which he earned from the work of his own hands.", "عن المقدام بن معديكرب رضي الله عنه"),
        HadithItem(150, "صحيح مسلم", "إن الله طيب لا يقبل إلا طيباً", "1015", "إن الله طيب لا يقبل إلا طيباً، وإن الله أمر المؤمنين بما أمر به المرسلين...", "Allah is Pure and accepts only that which is pure...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(151, "سنن الترمذي", "الربا والحرام محق للبركة", "1208", "لعن رسول الله صلى الله عليه وسلم آكل الربا وموكله وكاتبه وشاهديه، وقال: هم سواء.", "The Messenger of Allah cursed the consumer of interest, its payer, its scribe, and its two witnesses...", "عن عبد الله بن مسعود رضي الله عنه"),
        HadithItem(152, "صحيح البخاري", "اجتناب الشبهات في المال", "52", "الحلال بين والحرام بين، وبينهما أمور مشتبهات لا يعلمهن كثير من الناس، فمن اتقى الشبهات فقد استبرأ لدينه وعرضه.", "That which is lawful is clear and that which is unlawful is clear, and between them are doubtful matters...", "عن النعمان بن بشير رضي الله عنه"),
        HadithItem(153, "صحيح مسلم", "العارضة والإثم في المكاسب", "2553", "كالراعي يرعى حول الحمى يوشك أن يرتع فيه، ألا وإن لكل ملك حمى، ألا وإن حمى الله محارمه.", "Like a shepherd who pastures his flock around a sanctuary, nearly grazing in it...", "عن النعمان بن بشير رضي الله عنه"),
        HadithItem(154, "سنن أبي داود", "الأمانة والصدق في التجارة", "3442", "إن الله يقول: أنا ثالث الشريكين ما لم يخن أحدهما صاحبه، فإذا خانه خرجت من بينهما.", "Allah says: I am the third of two partners as long as one does not betray the other...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(155, "صحيح البخاري", "من اقتطع حق امرئ مسلم بيمينه", "2611", "من اقتطع حق امرئ مسلم بيمينه فقد أوجب الله له النار وحرم عليه الجنة.", "Whoever takes the right of a Muslim by a false oath, Allah makes the Fire obligatory for him...", "عن أبي أمامة الحارثي رضي الله عنه"),
        HadithItem(156, "صحيح مسلم", "النهي عن النجش واحتكار السلع", "1534", "لا تحتكر، فإنه لا يحتكر إلا خاطئ.", "Do not hoard goods, for none hoards except a sinner.", "عن معمر بن عبد الله رضي الله عنه"),
        HadithItem(157, "صحيح البخاري", "لا يبيع بعضكم على بيع بعض", "2139", "لا يبيع بعضكم على بيع بعض، ولا تناجشوا، ولا يبغض بعضكم بعضاً.", "Do not undersell one another, do not artificially inflate prices, and do not hate one another.", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(158, "صحيح مسلم", "النهي عن الحلف بالبيع لترويج السلعة", "1607", "الحلف منفقة للسلعة، ممحقة للبركة.", "Swearing an oath may sell the commodity, but it erases the blessing.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(159, "سنن الترمذي", "دع ما يريبك إلى ما لا يريبك", "2518", "دع ما يريبك إلى ما لا يريبك، فإن الصدق طمأنينة والكذب ريبة.", "Leave that which makes you doubt for that which does not make you doubt...", "عن الحسن بن علي رضي الله عنهما"),
        HadithItem(160, "صحيح البخاري", "ليأتين على الناس زمان لا يبالي المرء بما أخذ المال", "2083", "ليأتين على الناس زمان لا يبالي المرء بما أخذ المال، أمن حلال أم من حرام.", "A time will surely come upon people when a person will not care how he gains money, whether lawful or unlawful.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(161, "متفق عليه", "من كان تؤمن بالله واليوم الآخر فليقل خيراً أو ليصمت", "6018", "من كان يؤمن بالله واليوم الآخر فليقل خيراً أو ليصمت.", "Whoever believes in Allah and the Last Day should speak good or remain silent.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(162, "صحيح البخاري", "من يضمن لي ما بين لحييه وما بين رجليه", "6474", "من يضمن لي ما بين لحييه وما بين رجليه أضمن له الجنة.", "Whoever guarantees for me what is between his jaws and between his legs, I guarantee him Paradise.", "عن سهل بن سعد رضي الله عنه"),
        HadithItem(163, "سنن الترمذي", "وهل يكب الناس في النار على وجوههم إلا حصائد ألسنتهم", "2616", "وهل يكب الناس في النار على وجوههم أو على مناخرهم إلا حصائد ألسنتهم؟! ", "Are people thrown into the Fire on their faces for anything other than the harvests of their tongues?!", "عن معاذ بن جبل رضي الله عنه"),
        HadithItem(164, "صحيح مسلم", "إن العبد ليتكلم بالكلمة من رضوان الله", "2988", "إن العبد ليتكلم بالكلمة من رضوان الله لا يلقي لها بالاً يرفعه الله بها درجات، وإن العبد ليتكلم بالكلمة من سخط الله لا يلقي لها بالاً يهوي بها في جهنم.", "A servant speaks a word pleasing to Allah without giving it thought, by which Allah raises his status...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(165, "متفق عليه", "النهي عن الغيبة", "2589", "قيل: يا رسول الله ما الغيبة؟ قال: ذكرك أخاك بما يكره. قيل: أفرأيت إن كان في أخي ما أقول؟ قال: إن كان فيه ما تقول فقد اغتبته، وإن لم يكن فيه فقد بهتَّه.", "Backbiting is mentioning your brother with what he dislikes...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(166, "صحيح البخاري", "لا يدخل الجنة نمّام", "6056", "لا يدخل الجنة قتّات (نمّام).", "A talebearer (namwam) will not enter Paradise.", "عن حذيفة بن اليمان رضي الله عنه"),
        HadithItem(167, "صحيح مسلم", "النهي عن السب واللعن", "2599", "سباب المسلم فسوق، وقتاله كفر.", "Abusing a Muslim is wickedness, and fighting him is disbelief.", "عن عبد الله بن مسعود رضي الله عنه"),
        HadithItem(168, "سنن الترمذي", "ليس المؤمن بالطعان ولا اللعان", "1977", "ليس المؤمن بالطعان ولا اللعان ولا الفاحش ولا البذيء.", "The believer is not one who slanders, curses, speaks obscenities, or uses vulgar language.", "عن عبد الله بن مسعود رضي الله عنه"),
        HadithItem(169, "صحيح البخاري", "النهي عن الكذب والإفك", "6094", "وإياكم والكذب، فإن الكذب يهدي إلى الفجور، وإن الفجور يهدي إلى النار.", "Beware of lying, for lying leads to wickedness, and wickedness leads to the Fire.", "عن عبد الله بن مسعود رضي الله عنه"),
        HadithItem(170, "سنن أبي داود", "ويل للذي يحدث فيكذب ليضحك به القوم", "4990", "ويل للذي يحدث فيكذب ليضحك به القوم، ويل له ثم ويل له.", "Woe to him who speaks and lies to make people laugh; woe to him, woe to him.", "عن معاوية بن حيدة رضي الله عنه"),
        HadithItem(171, "صحيح مسلم", "المستبان ما قالا فعلى البادئ منهما", "2587", "المستبان ما قالا فعلى البادئ منهما حتى يعتدي المظلوم.", "The sin of two who abuse one another falls upon the one who initiated it, unless the wronged person transgresses.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(172, "صحيح البخاري", "من كان له وجهان في الدنيا", "7179", "تجدون شر الناس ذا الوجهين، الذي يأتي هؤلاء بوجه وهؤلاء بوجه.", "You will find among the worst people the two-faced person who comes to these with one face and those with another.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(173, "سنن الترمذي", "من كف لسانه ستر الله عورته", "2418", "من كف لسانه ستر الله عورته، ومن كظم غيظه وقاه الله عذابه.", "Whoever restrains his tongue, Allah conceals his faults, and whoever restrains his anger, Allah spares him His punishment.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(174, "صحيح مسلم", "كفى بالمرء كذباً أن يحدث بكل ما سمع", "5", "كفى بالمرء كذباً أن يحدث بكل ما سمع.", "It is sufficient lying for a person to narrate everything he hears.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(175, "صحيح البخاري", "آية المنافق ثلاث", "33", "آية المنافق ثلاث: إذا حدث كذب، وإذا وعد أخلف، وإذا اؤتمن خان.", "The signs of a hypocrite are three: when he speaks he lies, when he promises he breaks it, when trusted he betrays.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(176, "صحيح مسلم", "أربع من كن فيه كان منافقاً خالصاً", "58", "أربع من كن فيه كان منافقاً خالصاً، ومن كانت فيه خصلة منهن كانت فيه خصلة من النفاق حتى يدعها...", "Four qualities, whoever has them is a pure hypocrite...", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(177, "متفق عليه", "إياكم والظن فإن الظن أكذب الحديث", "6066", "إياكم والظن، فإن الظن أكذب الحديث، ولا تحسسوا، ولا تجسسوا، ولا تنافسوا، ولا تحاسدوا...", "Beware of suspicion, for suspicion is the falsest of speech. Do not spy, do not envy...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(178, "صحيح مسلم", "لا تحاسدوا ولا تباغضوا وكونوا عباد الله إخواناً", "2559", "لا تحاسدوا، ولا تناجشوا، ولا تباغضوا، ولا تدابروا، ولا يبيع بعضكم على بيع بعض، وكونوا عباد الله إخواناً.", "Do not envy one another, do not hate one another, do not turn away from one another, be brothers as servants of Allah.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(179, "سنن أبي داود", "الحسد يأكل الحسنات", "4903", "إياكم والحسد، فإن الحسد يأكل الحسنات كما تأكل النار الحطب.", "Beware of envy, for envy consumes good deeds as fire consumes wood.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(180, "صحيح البخاري", "من سمع سَمّع الله به ومن يراءِ يراءِ الله به", "6499", "من سَمّع سَمّع الله به، ومن يُرائي يُرائي الله به.", "Whoever seeks fame, Allah will expose him, and whoever acts to show off, Allah will show him off.", "عن جندب بن عبد الله رضي الله عنه"),
        HadithItem(181, "صحيح البخاري", "كن في الدنيا كأنك غريب أو عابر سبيل", "6416", "كن في الدنيا كأنك غريب أو عابر سبيل.", "Be in this world as if you were a stranger or a traveler passing through.", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(182, "صحيح مسلم", "الدنيا سجن المؤمن وجنة الكافر", "2956", "الدنيا سجن المؤمن وجنة الكافر.", "The world is a prison for the believer and a paradise for the disbeliever.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(183, "سنن الترمذي", "لو كانت الدنيا تعدل عند الله جناح بعوضة", "2320", "لو كانت الدنيا تعدل عند الله جناح بعوضة ما سقى كافراً منها شربة ماء.", "If the world were worth to Allah the wing of a mosquito, He would not have given a disbeliever a drink of water from it.", "عن سهل بن سعد رضي الله عنه"),
        HadithItem(184, "صحيح مسلم", "ما الدنيا في الآخرة إلا مثل ما يجعل أحدكم أصبعه في اليم", "2858", "ما الدنيا في الآخرة إلا مثل ما يجعل أحدكم أصبعه في اليم فلينظر بم يرجع!", "The world compared to the Hereafter is like one of you dipping his finger into the ocean...", "عن المستورد بن شداد رضي الله عنه"),
        HadithItem(185, "صحيح البخاري", "موضِع سوط أحدكم في الجنة خير من الدنيا وما فيها", "2892", "لموضع سوط أحدكم في الجنة خير من الدنيا وما فيها.", "A space in Paradise the size of a whip is better than this world and all that is in it.", "عن سهل بن سعد رضي الله عنه"),
        HadithItem(186, "صحيح مسلم", "أزهد الناس أورعهم وأقنعهم", "1054", "قد أفلح من أسلم، ورُزق كفافاً، وقنّعه الله بما آتاه.", "Successful indeed is he who submits, is provided with sufficient sustenance, and is content.", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(187, "سنن ابن ماجه", "ازهد في الدنيا يحبك الله وازهد فيما في أيدي الناس يحبك الناس", "4102", "ازهد في الدنيا يحبك الله، وازهد فيما في أيدي الناس يحبك الناس.", "Renounce the world and Allah will love you, renounce what people possess and people will love you.", "عن سهل بن سعد الساعدي رضي الله عنه"),
        HadithItem(188, "صحيح البخاري", "من كانت الآخرة همه", "6435", "من كانت الآخرة همه جعل الله غناه في قلبه وجمَع له شمله وأتته الدنيا وهي راغمة.", "Whoever makes the Hereafter his primary concern, Allah places richness in his heart...", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(189, "صحيح مسلم", "إن بين يدي الساعة لأياماً ينزل فيها الجهل", "2672", "إن بين يدي الساعة لأياماً ينزل فيها الجهل ويرفع فيها العلم ويكثر فيها الهرج (القتل).", "Before the Hour there will be days when ignorance descends, knowledge is taken away, and killing increases.", "عن عبد الله بن مسعود رضي الله عنه"),
        HadithItem(190, "صحيح البخاري", "اغتنم خبراً قبل خَمْس", "6417", "اغتنم خبراً قبل خَمْس: شبابك قبل هرمك، وصحتك قبل سقمك، وغناك قبل فقرك، وفراغك قبل شغلك، وحياتك قبل موتك.", "Take advantage of five before five: your youth before your old age, health before sickness...", "عن عبد الله بن عباس رضي الله عنهما"),
        HadithItem(191, "صحيح مسلم", "نعمتان مغبون فيهما كثير من الناس", "6412", "نعمتان مغبون فيهما كثير من الناس: الصحة والفراغ.", "Two blessings regarding which many people are cheated: health and free time.", "عن عبد الله بن عباس رضي الله عنهما"),
        HadithItem(192, "سنن الترمذي", "لا تزول قدما عبد يوم القيامة حتى يسأل عن أربع", "2417", "لا تزول قدما عبد يوم القيامة حتى يسأل عن أربع: عن عمره فيما أفناه، وعن علمه ما فعل به، وعن ماله من أين اكتسبه وفيما أنفقه، وعن جسمه فيما أبلاه.", "A servant's feet will not slip on Judgment Day until he is asked about four things...", "عن أبي برزة الأسلمي رضي الله عنه"),
        HadithItem(193, "متفق عليه", "يتبع الميت ثلاثة فيرجع اثنان ويبقى واحد", "6514", "يتبع الميت ثلاثة: أهله وماله وعمله، فيرجع اثنان ويبقى واحد: يرجع أهله وماله ويبقى عمله.", "Three follow the deceased: his family, wealth, and deeds. Two return and one remains: his deeds.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(194, "صحيح مسلم", "أكثروا من ذكر هادم اللذات", "2307", "أكثروا من ذكر هادم اللذات: الموت.", "Remember frequently the destroyer of pleasures: Death.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(195, "صحيح البخاري", "إذا مات أحدكم عرض عليه مقعده بالغداة والعشي", "1379", "إن أحدكم إذا مات عُرض عليه مقعده بالغداة والعشي، إن كان من أهل الجنة فمن أهل الجنة، وإن كان من أهل النار فمن أهل النار.", "When any of you dies, his seat is presented to him morning and evening...", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(196, "صحيح مسلم", "القبر أول منازل الآخرة", "2875", "إن القبر أول منزل من منازل الآخرة، فإن نجا منه فما بعده أيسر منه، وإن لم ينَجُ منه فما بعده أشد منه.", "The grave is the first stage of the Hereafter; if one is saved from it, what follows is easier...", "عن عثمان بن عفان رضي الله عنه"),
        HadithItem(197, "سنن أبي داود", "الموت تحفة المؤمن", "4210", "الموت تحفة المؤمن.", "Death is a gift to the believer.", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(198, "شعب الإيمان للبيهقي", "من أحب لقاء الله أحب الله لقاءه", "6507", "من أحب لقاء الله أحب الله لقاءه، ومنكره لقاء الله كره الله لقاءه.", "Whoever loves to meet Allah, Allah loves to meet him; whoever hates to meet Allah, Allah hates to meet him.", "عن عائشة أم المؤمنين رضي الله عنها"),
        HadithItem(199, "مسند أحمد", "يبعث كل عبد على ما مات عليه", "2878", "يبعث كل عبد على ما مات عليه.", "Every servant will be resurrected upon that which he died upon.", "عن جابر بن عبد الله رضي الله عنهما"),
        HadithItem(200, "صحيح مسلم", "خاتمة الخير وبنعمته تتم الصالحات", "2700", "الحمد لله الذي بنعمته تتم الصالحات، وإن الله لا ينظر إلى صوركم وأموالكم، ولكن ينظر إلى قلوبكم وأعمالكم.", "All praise is due to Allah by Whose grace righteous deeds are completed. Allah looks at your hearts and deeds.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(201, "صحيح مسلم", "التوبة مبسوطة اليدين", "2759", "إن الله عز وجل يبسط يده بالليل ليتوب المسيء بالنهار، ويبسط يده بالنهار ليتوب المسيء بالليل، حتى تطلع الشمس من مغربها.", "Allah extends His Hand at night to accept the repentance of the sinner of the day...", "عن أبي موسى الأشعري رضي الله عنه"),
        HadithItem(202, "متفق عليه", "فرح الله بتوبة عبده", "2744", "لَلَّهُ أشد فرحاً بتوبة عبده حين يتوب إليه من أحدكم كان على راحلته بأرض فلاة فإنفلتت منه وعليها طعامه وشرابه...", "Allah is more pleased with the repentance of His servant than one of you who loses his riding camel in a desert...", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(203, "صحيح مسلم", "التائب من الذنب كمن لا ذنب له", "2749", "التائب من الذنب كمن لا ذنب له.", "The one who repents from sin is like one who has no sin.", "عن عبد الله بن مسعود رضي الله عنه"),
        HadithItem(204, "سنن الترمذي", "كل بني آدم خطاء وخير الخطائين التوابون", "2499", "كل بني آدم خطاء وخير الخطائين التوابون.", "Every son of Adam commits sins, and the best of sinners are those who repent.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(205, "صحيح البخاري", "قصة قاتل مائة نفس", "3470", "كان فيمن كان قبلكم رجل قتل تسعة وتسعين نفساً... فسأل عن أعلم أهل الأرض فدُلّ على عالم فقال: إنه قتل مائة نفس فهل له من توبة؟ فقال: نعم...", "There was a man among those before you who killed ninety-nine people, then sought repentance...", "عن أبي سعيد الخدري رضي الله عنه"),
        HadithItem(206, "صحيح مسلم", "إن الله يقبل توبة العبد ما لم يغرغر", "2753", "إن الله يقبل توبة العبد ما لم يغرغر.", "Indeed Allah accepts the repentance of a servant as long as the death rattle has not begun.", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(207, "صحيح البخاري", "الندم توبة", "7169", "الندم توبة.", "Remorse is repentance.", "عن عبد الله بن مسعود رضي الله عنه"),
        HadithItem(208, "صحيح مسلم", "لو لم تذنبوا لذهب الله بكم", "2749", "والذي نفسي بيده لو لم تذنبوا لذهب الله بكم ولجاء بقوم يذنبون فيستغفرون الله فيغفر لهم.", "By Him in Whose Hand is my soul, if you did not sin Allah would replace you with people who sin and ask forgiveness...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(209, "سنن الترمذي", "اتق الله حيثما كنت", "1987", "اتق الله حيثما كنت وأتبع السيئة الحسنة تمحها وخالق الناس بخلق حسن.", "Fear Allah wherever you are, follow an evil deed with a good one, and treat people with good character.", "عن معاذ بن جبل رضي الله عنه"),
        HadithItem(210, "صحيح البخاري", "من استغفر في اليوم سبعين مرة", "6307", "والله إني لأستغفر الله وأتوب إليه في اليوم أكثر من سبعين مرة.", "By Allah, I seek forgiveness from Allah and repent to Him more than seventy times a day.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(211, "صحيح مسلم", "استغفار النبي في المجلس الواحد", "2702", "إنه ليغان على قلبي وإني لأستغفر الله في اليوم مائة مرة.", "Sometimes my heart is veiled, and I seek forgiveness from Allah a hundred times a day.", "عن الأغَرِّ المزني رضي الله عنه"),
        HadithItem(212, "سنن النسائي", "التقوى هاهنا", "2564", "التقوى هاهنا، ويشير إلى صدره ثلاث مرات.", "Piety is right here (pointing to his chest three times).", "عن أبي هريرة رضي الله عنه"),
        HadithItem(213, "صحيح مسلم", "اللهم آت نفسي تقواها", "2722", "اللهم آت نفسي تقواها وزكّها أنت خير من زكاها أنت وليها ومولاها.", "O Allah, grant my soul its piety and purify it, You are the best to purify it.", "عن زيد بن أرقم رضي الله عنه"),
        HadithItem(214, "سنن الترمذي", "أكثر ما يدخل الناس الجنة", "2004", "سُئل رسول الله عن أكثر ما يدخل الناس الجنة؟ فقال: تقوى الله وحسن الخلق.", "The Prophet was asked what enters people into Paradise most? He said: Fear of Allah and good character.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(215, "صحيح البخاري", "لا يبلغ العبد أن يكون من المتقين", "2451", "لا يبلغ العبد أن يكون من المتقين حتى يدع ما لا بأس به حذراً لما به البأس.", "A servant does not reach true piety until he leaves that which is harmless out of caution for what is harmful.", "عن عطية السعدي رضي الله عنه"),
        HadithItem(216, "صحيح مسلم", "البر حسن الخلق والإثم ما حاك في صدرك", "2553", "البر حسن الخلق والإثم ما حاك في نفسك وكرهت أن يطلع عليه الناس.", "Righteousness is good character, and sin is what wavers in your soul and you hate people seeing.", "عن النواس بن سمعان رضي الله عنه"),
        HadithItem(217, "سنن ابن ماجه", "المتقون السادة", "4221", "المؤمن الهين اللين كالجمل الأنف إن قيد انقاد وإن استُنخ على صخرة استناخ.", "The gentle believer is like a trained camel, if led he follows...", "عن ابن عمر رضي الله عنهما"),
        HadithItem(218, "صحيح البخاري", "من ترك شيئاً لله عوضه الله خيراً منه", "5671", "إنك لن تدع شيئاً لله عز وجل إلا أبدلك الله به ما هو خير لك منه.", "You will never leave anything for Allah except that Allah will replace it with something better for you.", "عن أبي قتادة رضي الله عنه"),
        HadithItem(219, "صحيح مسلم", "الورع والاحتياط في الدين", "1071", "إن الحلال بين وإن الحرام بين وبينهما أمور مشتبهات... فمن اتقى الشبهات فقد استبرأ لدينه وعرضه.", "Avoid doubtful matters to safeguard religion and honor.", "عن النعمان بن بشير رضي الله عنه"),
        HadithItem(220, "سنن الترمذي", "حاسبوا أنفسكم قبل أن تحاسبوا", "2459", "الكيِّس من دان نفسه وعمل لما بعد الموت، والعاجز من أتبع نفسه هواها وتمنى على الله الأماني.", "The wise person is he who calls himself to account and works for after death...", "عن شداد بن أوس رضي الله عنه"),
        HadithItem(221, "صحيح البخاري", "صلة الرحم معلقة بالعرش", "5989", "الرحم شجنة من الرحمن، قال الله تعالى: من وصلك وصلته ومن قطعك قطعتُه.", "Kinship is a branch from the Merciful; Allah said: Whoever joins you I join him, whoever cuts you I cut him.", "عن عائشة أم المؤمنين رضي الله عنها"),
        HadithItem(222, "صحيح مسلم", "أعجل الطاعة ثواباً صلة الرحم", "2556", "ليس شيء أطوع لله ولا أعجل ثواباً من صلة الرحم.", "Nothing is more obedient to Allah nor quicker in reward than maintaining ties of kinship.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(223, "صحيح البخاري", "الواصل ليس بالمكافئ", "5991", "ليس الواصل بالمكافئ، ولكن الواصل الذي إذا قطعت رحمه وصلها.", "The true maintainer of kinship is not the one who merely responds in kind, but who reconnects when severed.", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(224, "صحيح مسلم", "صلة الأقارب وإن جفاك الأقارب", "2558", "يا رسول الله، إن لي قرابة أصلهم ويقطعونني، وأحسن إليهم ويسيؤون إلي... فقال: لئن كنت كما قلت فكأنما تسفّهم المَلَّ ولا يزال معك من الله ظهير عليهم.", "A man said: I have relatives I visit but they cut me off... The Prophet said: If so, Allah is your helper against them.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(225, "سنن الترمذي", "فضل الصدقة على الأقارب", "658", "الصدقة على المسكين صدقة، وهي على ذي الرحم ثنتان: صدقة وصلة.", "Charity given to the poor is charity, and given to relatives is two things: charity and connecting kinship.", "عن سلمان بن عامر رضي الله عنه"),
        HadithItem(226, "صحيح البخاري", "بر الوالدين بعد موتهما", "5972", "هل بقي من بر أَبَوَيَّ شيء أَبَرُّهُما به بعد موتهما؟ قال: نعم، الصلاة عليهما، والاستغفار لهما، وإيقاد عهدهما، وصلة الرحم التي لا توصل إلا بهما.", "Is there any righteousness left I can do for my parents after death? He said: Yes, praying for them, seeking forgiveness...", "عن أبي أُسيد الساعدي رضي الله عنه"),
        HadithItem(227, "صحيح مسلم", "رضا الرب في رضا الوالد", "2548", "رضا الرب في رضا الوالد، وسخط الرب في سخط الوالد.", "The pleasure of the Lord is in the pleasure of the parent, and His wrath is in the wrath of the parent.", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(228, "متفق عليه", "عقوق الوالدين من الكبائر", "5976", "ألا أنبئكم بأكبر الكبائر؟ الإشراك بالله، وعقوق الوالدين، وكان متكئاً فجلس فقال: ألا وقول الزور وشهادة الزور.", "Shall I not inform you of the greatest sins? Shirk, disobedience to parents, and false testimony.", "عن أبي بكرة رضي الله عنه"),
        HadithItem(229, "صحيح البخاري", "الخالة بمنزلة الأم", "4251", "الخالة بمنزلة الأم.", "The maternal aunt is in the position of the mother.", "عن البراء بن عازب رضي الله عنه"),
        HadithItem(230, "صحيح مسلم", "إكرام صديق الأب بعد موته", "2552", "إن أبر البر صلة الرجل أهل ود أبيه بعد أن يولي.", "The finest act of virtue is for a man to maintain contact with his father's friends after he passes.", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(231, "متفق عليه", "وصية جبريل بالجار", "6015", "ما زال جبريل يوصيني بالجار حتى ظننت أنه سيورثه.", "Gabriel kept recommending the neighbor to me until I thought he would make him an heir.", "عن عائشة وابن عمر رضي الله عنهم"),
        HadithItem(232, "صحيح مسلم", "من كان يؤمن بالله واليوم الآخر فليحسن إلى جاره", "48", "من كان يؤمن بالله واليوم الآخر فليحسن إلى جاره.", "Whoever believes in Allah and the Last Day should be good to his neighbor.", "عن أبي شريح رضي الله عنه"),
        HadithItem(233, "سنن الترمذي", "خير الجيران عند الله خيرهم لجاره", "1944", "خير الأصحاب عند الله خيرهم لصاحبه، وخير الجيران عند الله خيرهم لجاره.", "The best of companions to Allah is the best to his companion, and the best of neighbors is the best to his neighbor.", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(234, "صحيح البخاري", "لا تحقرن جارة لجارتها ولو فرسن شاة", "6017", "يا نساء المسلمات، لا تحقرن جارة لجارتها ولو فِرْسَنَ شاة (ظلف شاة).", "O Muslim women, let no neighbor belittle a gift to her neighbor, even if it is a sheep's hoof.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(235, "صحيح مسلم", "لا يمنع جار جاره أن يغرز خشبة في جداره", "1609", "لا يمنع جار جاره أن يغرز خشبة في جداره.", "No neighbor should prevent his neighbor from fixing a wooden peg into his wall.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(236, "مسند أحمد", "ليس المؤمن الذي يشبع وجاره جائع إلى جنبه", "13803", "ليس المؤمن الذي يشبع وجاره جائع إلى جنبه وهو يعلم.", "He is not a true believer who eats his fill while his neighbor beside him is hungry.", "عن عبد الله بن عباس رضي الله عنهما"),
        HadithItem(237, "صحيح البخاري", "حق الجار الأقرب بابا", "6019", "قلت: يا رسول الله، إن لي جارين فإلى أيهما أهدي؟ قال: إلى أقربهما منك باباً.", "Aisha asked: I have two neighbors, to which shall I send gifts? He said: To the one whose door is closer.", "عن عائشة أم المؤمنين رضي الله عنها"),
        HadithItem(238, "سنن أبي داود", "أربعين داراً جوار", "5154", "الجيران ثلاثة: جار له حق واحد، وجار له حقان، وجار له ثلاثة حقوق...", "Neighbors are of three types: one with one right, one with two rights, and one with three rights...", "عن جابر بن عبد الله رضي الله عنهما"),
        HadithItem(239, "صحيح مسلم", "إفشاء السلام بين المسلمين", "54", "لا تدخلون الجنة حتى تؤمنوا، ولا تؤمنوا حتى تحابوا، أولا أدلكم على شيء إذا فعلتموه تحاببتم؟ أفشوا السلام بينكم.", "You will not enter Paradise until you believe, and you will not believe until you love one another...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(240, "صحيح البخاري", "السلام على من عرفت ومن لم تعرف", "28", "أي الإسلام خير؟ قال: تطعم الطعام، وتقرأ السلام على من عرفت ومن لم تعرف.", "Which Islam is best? He said: Feeding people food, and greeting with peace those you know and don't know.", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(241, "سنن الترمذي", "أقرب ما يكون الرب من العبد في جوف الليل الآخر", "3579", "أقرب ما يكون الرب من العبد في جوف الليل الآخر، فإن استطعت أن تكون ممن يذكر الله في تلك الساعة فكن.", "The Lord is closest to His servant in the depth of the late night...", "عن عمرو بن عبسة رضي الله عنه"),
        HadithItem(242, "صحيح مسلم", "الدعاء بين الأذان والإقامة لا يرد", "2738", "الدعاء لا يرد بين الأذان والإقامة.", "Supplication between Adhan and Iqamah is not turned down.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(243, "صحيح البخاري", "ساعة الإجابة يوم الجمعة", "935", "إن في الجمعة لساعة لا يوافقها عبد مسلم وهو قائم يصلي يسأل الله شيئاً إلا أعطاه إياه.", "There is an hour on Friday when any Muslim servant praying and asking Allah for good receives it.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(244, "سنن الترمذي", "الدعاء عند نزول المطر وفي السفر", "3595", "ثنتان ما تردان: الدعاء عند النداء، وتحت المطر.", "Two supplications are not rejected: at the call to prayer, and under the rain.", "عن سهل بن سعد رضي الله عنه"),
        HadithItem(245, "صحيح مسلم", "دعوة الصائم حتى يفطر", "2741", "ثلاثة لا ترد دعوتهم: الصائم حتى يفطر، والإمام العادل، ودعوة المظلوم.", "Three supplications are not rejected: the fasting person until he breaks fast, the just ruler, and the oppressed.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(246, "صحيح البخاري", "دعوة المظلوم ليس بينها وبين الله حجاب", "1496", "واتق دعوة المظلوم، فإنها ليس بينها وبين الله حجاب.", "Beware of the supplication of the oppressed, for there is no barrier between it and Allah.", "عن عبد الله بن عباس رضي الله عنهما"),
        HadithItem(247, "سنن أبي داود", "اعزموا المسألة في الدعاء", "1483", "إذا دعا أحدكم فلا يقل: اللهم اغفر لي إن شئت، ولكن ليعزم المسألة وليعظم الرغبة فإن الله لا يتعاظمه شيء أعطاه.", "When one of you supplicates, let him resolve his request firmly and not say 'if You wish'...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(248, "صحيح مسلم", "سلوا الله الشفاء والعافية", "2725", "سلوا الله العفو والعافية، فإن أحداً لم يُعطَ بعد اليقين خيراً من العافية.", "Ask Allah for pardon and well-being, for no one is given after certainty anything better than well-being.", "عن أبي بكر الصديق رضي الله عنه"),
        HadithItem(249, "سنن الترمذي", "دعاء النبي اللهم إني أسألك الهدى والتقى والعفاف والغنى", "3489", "اللهم إني أسألك الهدى والتقى والعفاف والغنى.", "O Allah, I ask You for guidance, piety, chastity, and self-sufficiency.", "عن عبد الله بن مسعود رضي الله عنه"),
        HadithItem(250, "صحيح مسلم", "اللهم أصلح لي ديني الذي هو عصمة أمري", "2720", "اللهم أصلح لي ديني الذي هو عصمة أمري، وأصلح لي دنياي التي فيها معاشي، وأصلح لي آخرتي التي فيها معادي...", "O Allah, set right for me my religion which is the safeguard of my affairs...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(251, "صحيح البخاري", "دعاء يامقلب القلوب ثبت قلبي على دينك", "6340", "يا مقلب القلوب ثبت قلبي على دينك.", "O Turner of the hearts, make my heart firm upon Your religion.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(252, "سنن الترمذي", "اسم الله الأعظم الذي إذا دعي به أجاب", "3475", "اللهم إني أسألك بأني أشهد أنك أنت الله لا إله إلا أنت الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفواً أحد...", "O Allah, I ask You testifying that You are Allah, there is no god but You, the One, the Eternal...", "عن بريدة بن الحصيب رضي الله عنه"),
        HadithItem(253, "صحيح مسلم", "أفضل الاستغفار في أطراف النهار", "2723", "من قال أستغفر الله الذي لا إله إلا هو الحي القيوم وأتوب إليه غُفرت ذنوبه وإن كان فاراً من الزحف.", "Whoever says 'I seek forgiveness from Allah, there is no god but Him...', his sins are forgiven.", "عن زيد مولى النبي رضي الله عنه"),
        HadithItem(254, "سنن أبي داود", "طوبى لمن وجد في صحيفته استغفاراً كثيراً", "1518", "طوبى لمن وجد في صحيفته استغفاراً كثيراً.", "Blessed is he who finds in his record of deeds much seeking of forgiveness.", "عن عبد الله بن بسر رضي الله عنه"),
        HadithItem(255, "صحيح البخاري", "دعاء الاستخارة في الأمور كلها", "1166", "كان رسول الله يعلمنا الاستخارة في الأمور كلها كما يعلمنا السورة من القرآن...", "The Messenger of Allah used to teach us Istikharah in all matters as he taught us a surah...", "عن جابر بن عبد الله رضي الله عنهما"),
        HadithItem(256, "صحيح مسلم", "دعاء المريض بالشفاء", "2202", "ضع يدك على الذي ألمّ من جسدك وقل: بسم الله ثلاثاً، وقل سبع مرات: أعوذ بالله وقدرته من شر ما أجد وأحاذر.", "Place your hand on the painful area of your body and say 'Bismillah' 3 times, then say 7 times 'I seek refuge in Allah'...", "عن عثمان بن أبي العاص رضي الله عنه"),
        HadithItem(257, "سنن الترمذي", "اللهم إنك عفو تحب العفو فاعف عني", "3513", "قلت: يا رسول الله أرأيت إن علمت أي ليلة ليلة القدر ما أقول فيها؟ قال: قولي: اللهم إنك عفو تحب العفو فاعف عني.", "Aisha asked what to say on Laylat al-Qadr; he said: Say 'O Allah, You are Pardoning and love pardoning, so pardon me'.", "عن عائشة أم المؤمنين رضي الله عنها"),
        HadithItem(258, "صحيح البخاري", "دعاء دخول الخلاء والخروج منه", "142", "إذا دخل الخلاء قال: اللهم إني أعوذ بك من الخُبْث والخبائث.", "When entering the restroom say: O Allah, I seek refuge in You from impure spirits.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(259, "صحيح مسلم", "دعاء النوم والاستيقاظ", "2711", "باسمك ربي وضعت جنبي وبك أرفعه، إن أمسكت نفسي فارحمها، وإن أرسلتها فاحفظها بما تحفظ به عبادك الصالحين.", "In Your name, my Lord, I lay down my side and in Your name I raise it...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(260, "صحيح البخاري", "دعاء السفر والترحال", "3082", "الله أكبر الله أكبر الله أكبر، سبحان الذي سخر لنا هذا وما كنا له مقرنين وإنا إلى ربنا لمنقلبون.", "Allah is the Greatest (3 times), Glory be to Him Who has subjected this to us...", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(261, "صحيح مسلم", "مفتاح الصلاة الطهور", "224", "مفتاح الصلاة الطهور، وتحريمها التكبير، وتحليلها التسليم.", "The key to prayer is purification, its entrance is Takbir, and its end is Taslim.", "عن علي بن أبي طالب رضي الله عنه"),
        HadithItem(262, "متفق عليه", "لا تقبل صلاة بغير طهور", "225", "لا تقبل صلاة بغير طهور، ولا صدقة من غلول.", "No prayer is accepted without purification, nor charity from unlawful gain.", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(263, "صحيح البخاري", "فضل الوضوء وإسباغه", "136", "إن أمتي يدعون يوم القيامة غرّاً محجلين من آثار الوضوء، فمن استطاع منكم أن يطيل غرته فليفعل.", "My nation will be called on Judgment Day bright-faced and bright-limbed from traces of Wudu...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(264, "صحيح مسلم", "تساقط الخطايا مع قطر الماء", "244", "إذا توضأ العبد المسلم فغسل وجهه خرجت من وجهه كل خطيئة نظر إليها بعينيه مع الماء أو مع آخر قطر الماء...", "When a Muslim servant performs Wudu and washes his face, every sin committed by eyes washes away...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(265, "سنن أبي داود", "فضل السواك في الوضوء", "46", "لولا أن أشق على أمتي لأمرتهم بالسواك مع كل وضوء.", "Were it not that it would burden my nation, I would have ordered them to use Miswak with every Wudu.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(266, "صحيح مسلم", "الذكر بعد الوضوء وفتح أبواب الجنة", "234", "ما منكم من أحد يتوضأ فيسبغ الوضوء ثم يقول: أشهد أن لا إله إلا الله وحده لا شريك له وأشهد أن محمداً عبده ورسوله إلا فتحت له أبواب الجنة الثمانية.", "No one performs Wudu thoroughly then says 'I testify there is no god but Allah...' except the 8 gates of Paradise open.", "عن عمر بن الخطاب رضي الله عنه"),
        HadithItem(267, "صحيح البخاري", "صفة وضوء النبي", "159", "توضأ ثلاثاً ثلاثاً، ثم قال: من توضأ نحو وضوئي هذا ثم قام فصلّى ركعتين لا يحدّث فيهما نفسه غُفر له ما تقدم من ذنبه.", "He performed Wudu washing three times each, then said: Whoever performs Wudu like mine then prays 2 rak'ahs sinlessly...", "عن عثمان بن عفان رضي الله عنه"),
        HadithItem(268, "صحيح مسلم", "المسح على الخفين والعمامة", "274", "جعل رسول الله ثلاثة أيام ولياليهن للمسافر، ويوماً وليلة للمقيم، يعني في المسح على الخفين.", "The Messenger of Allah specified three days and nights for the traveler and one day and night for the resident for wiping over leather socks.", "عن علي بن أبي طالب رضي الله عنه"),
        HadithItem(269, "سنن الترمذي", "التيمم صعيد طيب", "124", "الصعيد الطيب طهور المسلم وإن لم يجد الماء عشر سنين، فإذا وجد الماء فليمنَّه بشرته.", "Clean earth is a purifier for a Muslim even if he does not find water for ten years.", "عن أبي ذر الغفاري رضي الله عنه"),
        HadithItem(270, "صحيح البخاري", "الغسل يوم الجمعة واجب على كل محتلم", "877", "غُسل يوم الجمعة واجب على كل محتلم، وأن يستنَّ وبأن يمسّ طيباً إن وجد.", "Taking a bath on Friday is an obligation upon every mature person...", "عن أبي سعيد الخدري رضي الله عنه"),
        HadithItem(271, "صحيح مسلم", "السنن الفطرة خمس", "257", "الفطرة خمس: الختان، والاستحداد، وقص الشارب، وتقليم الأظفار، ونتف الإبط.", "Five things are from natural disposition: circumcision, shaving pubic hair, trimming mustache, clipping nails, plucking armpit hair.", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(272, "سنن أبي داود", "تنزّهوا من البول", "20", "استنزهوا من البول، فإن عامة عذاب القبر منه.", "Be careful to clean yourselves from urine, for most grave punishment comes from it.", "عن أَنَسِ بْنِ مَالِكٍ رضي الله عنه"),
        HadithItem(273, "صحيح البخاري", "إذا استيقظ أحدكم من نومه فلا يغمس يده في الإناء", "162", "إذا استيقظ أحدكم من نومه فلا يغمس يده في الإناء حتى يغسلها ثلاثاً، فإن أحدكم لا يدري أين باتت يده.", "When one of you wakes from sleep he should not dip his hand in a vessel until he washes it three times...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(274, "صحيح مسلم", "الماء طهور لا ينجسه شيء", "225", "إن الماء طهور لا ينجسه شيء إلا ما غلب على ريحه وطعمه ولونه.", "Water is pure and nothing makes it impure unless its odor, taste, or color is overcome.", "عن أبي سعيد الخدري رضي الله عنه"),
        HadithItem(275, "سنن الترمذي", "إذا ولغ الكلب في إناء أحدكم", "91", "إذا ولغ الكلب في إناء أحدكم فليغسله سبع مرات أولاهن بالتراب.", "If a dog licks the vessel of one of you, let him wash it seven times, the first with dust.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(276, "صحيح البخاري", "النهي عن استقبال القبلة واستدبارها عند الخلاء", "144", "إذا أتيتم الغائط فلا تستقبلوا القبلة ولا تستدبروها ببول ولا غائط، ولكن شرقوا أو غربوا.", "When going to answer nature's call do not face the Qiblah nor turn your back to it...", "عن أبي أيوب الأنصاري رضي الله عنه"),
        HadithItem(277, "صحيح مسلم", "لا يمسن أحدكم ذكره بيمينه وهو يبول", "267", "لا يمسن أحدكم ذكره بيمينه وهو يبول، ولا يتمسح من الخلاء بيمينه.", "No one should touch his private part with his right hand while urinating nor wipe with right hand.", "عن أبي قتادة رضي الله عنه"),
        HadithItem(278, "صحيح البخاري", "فضل إسباغ الوضوء في البرد", "137", "إسباغ الوضوء في المكاره يمحو الله به الخطايا ويرفع به الدرجات.", "Thoroughly performing Wudu under difficult conditions wipes away sins...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(279, "صحيح مسلم", "السواك مطهرة للفم مرضاة للرب", "255", "السواك مطهرة للفم مرضاة للرب.", "The Miswak is a means of purification for the mouth and pleasing to the Lord.", "عن عائشة أم المؤمنين رضي الله عنها"),
        HadithItem(280, "سنن الترمذي", "تحريم ما حرم الله وتطهير الجسد", "308", "طهّروا هذه الأجساد طهّركم الله، فإنه ليس من عبد يبيل طاهراً إلا بات معه ملك في شعاره.", "Purify these bodies, may Allah purify you, for no servant sleeps pure except an angel stays in his garment.", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(281, "صحيح البخاري", "من صام رمضان إيماناً واحتساباً", "38", "من صام رمضان إيماناً واحتساباً غُفر له ما تقدم من ذنبه.", "Whoever fasts Ramadan out of faith and seeking reward, his past sins will be forgiven.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(282, "صحيح مسلم", "من قام رمضان إيماناً واحتساباً", "759", "من قام رمضان إيماناً واحتساباً غُفر له ما تقدم من ذنبه.", "Whoever prays during the nights of Ramadan out of faith and seeking reward, his past sins are forgiven.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(283, "متفق عليه", "من قام ليلة القدر إيماناً واحتساباً", "2014", "من قام ليلة القدر إيماناً واحتساباً غُفر له ما تقدم من ذنبه.", "Whoever stands in prayer on Laylat al-Qadr out of faith and seeking reward is forgiven.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(284, "صحيح مسلم", "الصيام جنة وحصن حصين", "1151", "الصيام جُنَّة، فإذا كان يوم صوم أحدكم فلا يرفث ولا يصخب، فإن سابَّه أحد أو قاتله فليقل: إني امرؤ صائم.", "Fasting is a shield; when one of you is fasting he should not speak obscenities nor shout...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(285, "صحيح البخاري", "للصائم فرحتان", "1904", "للصائم فرحتان يفرحهما: إذا أفطر فرح بفطره، وإذا لقي ربه فرح بصومه.", "The fasting person has two occasions of joy: when he breaks his fast, and when he meets his Lord.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(286, "صحيح مسلم", "خلوف فم الصائم أطيب عند الله من ريح المسك", "1151", "والذي نفس محمد بيده لخلوف فم الصائم أطيب عند الله يوم القيامة من ريح المسك.", "By Him in Whose Hand is Muhammad's soul, the breath of a fasting person is sweeter to Allah than musk.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(287, "متفق عليه", "باب الريان للصائمين", "1896", "إن في الجنة باباً يقال له الريان يدخل منه الصائمون يوم القيامة لا يدخل منه أحد غيرهم...", "In Paradise there is a gate called Ar-Rayyan through which only fasting people will enter...", "عن سهل بن سعد رضي الله عنه"),
        HadithItem(288, "صحيح البخاري", "تسحروا فإن في السحور بركة", "1923", "تسحروا فإن في السحور بركة.", "Eat Suhoor, for indeed in Suhoor there is blessing.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(289, "صحيح مسلم", "تعجيل الفطر", "1098", "لا يزال الناس بخير ما عجلوا الفطر.", "People will remain in goodness as long as they hasten breaking the fast.", "عن سهل بن سعد رضي الله عنه"),
        HadithItem(290, "سنن الترمذي", "من فطر صائماً كان له مثل أجره", "807", "من فطر صائماً كان له مثل أجره غير أنه لا ينقص من أجر الصائم شيئاً.", "Whoever provides food for a fasting person to break fast gets a reward equal to his without decreasing his reward.", "عن زيد بن خالد الجهني رضي الله عنه"),
        HadithItem(291, "صحيح البخاري", "من لم يدع قول الزور والعمل به", "1903", "من لم يدع قول الزور والعمل به والجهل فليس لله حاجة في أن يدع طعامه وشرابه.", "Whoever does not leave false speech and acting upon it, Allah has no need for him to leave food and drink.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(292, "صحيح مسلم", "صيام ستة أيام من شوال", "1164", "من صام رمضان ثم أتبعه ستاً من شوال كان كصيام الدهر.", "Whoever fasts Ramadan then follows it with six days of Shawwal, it is like fasting perpetually.", "عن أبي أيوب الأنصاري رضي الله عنه"),
        HadithItem(293, "صحيح مسلم", "صيام يوم عرفة ويكفر سنتين", "1162", "صيام يوم عرفة أحتسب على الله أن يكفر السنة التي قبله والسنة التي بعده.", "Fasting the day of Arafah, I hope Allah expiates the year before and the year after.", "عن أبي قتادة الأنصاري رضي الله عنه"),
        HadithItem(294, "صحيح مسلم", "صيام يوم عاشوراء", "1163", "صيام يوم عاشوراء أحتسب على الله أن يكفر السنة التي قبله.", "Fasting the day of Ashura, I hope Allah expiates the year before.", "عن أبي قتادة الأنصاري رضي الله عنه"),
        HadithItem(295, "سنن النسائي", "صيام ثلاثة أيام من كل شهر", "2418", "أوصاني خليلي بثلاث: صيام ثلاثة أيام من كل شهر، وركعتي الضحى، وأن أُوتر قبل أن أنام.", "My close friend advised me three things: fasting 3 days of every month, 2 rak'ahs of Duha, and Witr before sleeping.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(296, "صحيح البخاري", "أفضل الصيام صيام داود", "1976", "أحب الصيام إلى الله صيام داود كان يصوم يوماً ويُفطر يوماً.", "The most beloved fasting to Allah is the fasting of David: he fasted one day and broke fast the next.", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(297, "صحيح مسلم", "قيام الليل دأب الصالحين", "1163", "عليكم بقيام الليل فإنه دأب الصالحين قبلكم ومقربة إلى ربكم وتكفير للسيئات ومطردة للداء عن الجسد.", "Adhere to night prayer, for it was the habit of the righteous before you and brings closeness to your Lord...", "عن بلال بن رباح رضي الله عنه"),
        HadithItem(298, "صحيح البخاري", "كان النبي يقوم الليل حتى تتفطر قدماه", "4837", "كان النبي يقوم من الليل حتى تتفطر قدماه، فقيل له: أتفعل هذا وقد غُفر لك ما تقدم من ذنبك وما تأخر؟! قال: أفلا أكون عبداً شكوراً!", "The Prophet prayed at night until his feet swelled; when asked why, he said: Should I not be a grateful servant!", "عن المغيرة بن شعبة رضي الله عنه"),
        HadithItem(299, "صحيح مسلم", "أقرب ما يكون الرب في ثلث الليل الآخر", "758", "ينزل الله إلى السماء الدنيا كل ليلة حين يبقى ثلث الليل الآخر فيقول: هل من داعٍ فأستجيب له...", "Allah descends to the lowest heaven during the last third of night asking: Is there any caller I may answer...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(300, "سنن الترمذي", "من قام بعشر آيات لم يكتب من الغافلين", "2617", "من قام بعشر آيات لم يُكتب من الغافلين، ومن قام بمائة آية كُتب من القانتين، ومن قام بألف آية كُتب من المقنطرين.", "Whoever stands praying with 10 verses is not recorded among the negligent...", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(301, "صحيح البخاري", "الاستئذان ثلاث فإن أُذن لك وإلا فارجع", "6245", "الاستئذان ثلاث، فإن أُذن لك وإلا فارجع.", "Seeking permission is three times; if given enter, otherwise return.", "عن أبي موسى الأشعري رضي الله عنه"),
        HadithItem(302, "صحيح مسلم", "إنما جعل الاستئذان من أجل البصر", "2156", "إنما جعل الاستئذان من أجل البصر.", "Seeking permission was ordained solely because of sight.", "عن سهل بن سعد رضي الله عنه"),
        HadithItem(303, "صحيح البخاري", "لا يتناجى اثنان دون الثالث", "6290", "إذا كنتم ثلاثة فلا يتناجى اثنان دون صاحبهم فإن ذلك يحزنه.", "If you are three, two should not whisper together excluding the third, as that saddens him.", "عن عبد الله بن مسعود رضي الله عنه"),
        HadithItem(304, "صحيح مسلم", "المجالس بالأمانة", "2170", "المجالس بالأمانة إلا ثلاثة مجالس: سفك دم حرام، أو فرج حرام، أو اقتطاع مال بغير حق.", "Gatherings are held in trust except three: shedding unlawful blood, unlawful intimacy, or taking wealth unjustly.", "عن جابر بن عبد الله رضي الله عنهما"),
        HadithItem(305, "سنن الترمذي", "كفارة المجلس", "3433", "من جلس في مجلس فكثر فيه لغطه فقال قبل أن يقوم: سبحانك اللهم وبحمدك أشهد أن لا إله إلا أنت أستغفرك وأتوب إليك إلا غُفر له ما كان في مجلسه.", "Whoever sits in a gathering and utters 'Glory to You O Allah...', his sins in that gathering are forgiven.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(306, "صحيح البخاري", "تسمية الله عند الأكل والأكل باليمين", "5376", "يا غلام، سمِّ الله، وكل بيمينك، وكل مما يليك.", "O boy, say Bismillah, eat with your right hand, and eat from what is near you.", "عن عمر بن أبي سلمة رضي الله عنه"),
        HadithItem(307, "صحيح مسلم", "إذا أكل أحدكم فليأكل بيمينه وليشرب بيمينه", "2020", "إذا أكل أحدكم فليأكل بيمينه وإذا شرب فليشرب بيمينه فإن الشيطان يأكل بيمينه ويشرب بشماله.", "When one of you eats let him eat with his right hand, for Satan eats with his left.", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(308, "سنن الترمذي", "حمد الله بعد الأكل والشرب", "1810", "إن الله ليرضى عن العبد أن يأكل الأكلة فيحمده عليها، أو يشرب الشربة فيحمده عليها.", "Allah is pleased with a servant who eats food and praises Him for it, or drinks and praises Him for it.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(309, "صحيح البخاري", "ما عاب النبي طعاماً قط", "5409", "ما عاب النبي صلى الله عليه وسلم طعاماً قط، إن اشتهاه أكله وإلا تركه.", "The Prophet never criticized any food; if he liked it he ate, otherwise he left it.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(310, "صحيح مسلم", "النهي عن الشرب قائماً", "2024", "لا يشربن أحد منكم قائماً، فمن نسي فليستقئ.", "None of you should drink standing up; whoever forgets should vomit.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(311, "صحيح البخاري", "إطفاء السرج وإغلاق الأبواب ليلاً", "3280", "أطفئوا المصابيح إذا رقدتم، وأغلقوا الأبواب، وأوكئوا السقاء، وخمروا الطعام والشراب.", "Extinguish lamps when you sleep, lock doors, tie water skins, and cover food and drink.", "عن جابر بن عبد الله رضي الله عنهما"),
        HadithItem(312, "صحيح مسلم", "تشميت العاطس إذا حمد الله", "2992", "إذا عطس أحدكم فحمد الله فشمِّتوه، فإن لم يحمد الله فلا تشمِّتوه.", "If one of you sneezes and praises Allah, respond 'Yarhamukullah'; if he doesn't, do not.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(313, "صحيح البخاري", "حق العاطس على المسلم", "6224", "إذا عطس أحدكم فليقل: الحمد لله، وليقل له أخوه: يرحمك الله، فإذا قال له يرحمك الله فليقل: يهديكم الله ويصلح بالكم.", "When sneezing say Alhamdulillah, your brother says Yarhamukullah, then reply Yahdeekumullah...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(314, "سنن أبي داود", "التثاؤب من الشيطان فليكظم ما استطاع", "5028", "التثاؤب من الشيطان، فإذا تثاءب أحدكم فليكظم ما استطاع.", "Yawning is from Satan; when one of you yawns let him restrain it as much as possible.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(315, "صحيح مسلم", "إماطة الأذى عن الطريق صدقة", "2699", "وتُميط الأذى عن الطريق صدقة.", "Removing harmful objects from the road is a charity.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(316, "صحيح البخاري", "لا يحل لمسلم أن يهجر أخاه فوق ثلاث", "6077", "لا يحل لمسلم أن يهجر أخاه فوق ثلاث ليال، يلتقيان فيُعرض هذا ويُعرض هذا، وخيرهما الذي يبدأ بالسلام.", "It is not lawful for a Muslim to boycott his brother for more than three nights...", "عن أبي أيوب الأنصاري رضي الله عنه"),
        HadithItem(317, "صحيح مسلم", "أنزلوا الناس منازلهم", "2168", "أنزلوا الناس منازلهم.", "Treat people according to their status and dignity.", "عن عائشة أم المؤمنين رضي الله عنها"),
        HadithItem(318, "سنن الترمذي", "ليس منا من لم يرحم صغيرنا ويوقر كبيرنا", "1919", "ليس منا من لم يرحم صغيرنا، ويفهم حق كبيرنا.", "He is not of us who does not show mercy to our young nor respect the rights of our elders.", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(319, "صحيح البخاري", "المؤلفات قلوبهم وإكرام الكريم", "6022", "إذا أتاكم كريم قوم فأكرموه.", "When the honorable leader of a people comes to you, show him honor.", "عن جرير بن عبد الله رضي الله عنه"),
        HadithItem(320, "صحيح مسلم", "تيسير الأمور والتطمين", "1732", "يسروا ولا تعسروا، وبشروا ولا تنفروا.", "Make things easy and do not make them difficult, give good tidings and do not repel people.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(321, "سنن ابن ماجه", "طلب العلم فريضة على كل مسلم", "224", "طلب العلم فريضة على كل مسلم.", "Seeking knowledge is an obligation upon every Muslim.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(322, "صحيح مسلم", "من سلك طريقاً يبتغي فيه علماً", "2699", "من سلك طريقاً يبتغي فيه علماً سهّل الله له به طريقاً إلى الجنة، وإن الملائكة لتضع أجنحتها لطلب العلم رضا بما يصنع.", "Whoever treads a path seeking knowledge Allah eases his way to Paradise, and angels lower their wings for him...", "عن أبي الدرداء رضي الله عنه"),
        HadithItem(323, "صحيح البخاري", "فضل العالم على العابد", "100", "فضل العالم على العابد كفضل القمر على سائر الكواكب.", "The superiority of the scholar over the worshiper is like the moon over all other stars.", "عن أبي الدرداء رضي الله عنه"),
        HadithItem(324, "سنن الترمذي", "من خرج في طلب العلم فهو في سبيل الله", "2647", "من خرج في طلب العلم فهو في سبيل الله حتى يرجع.", "Whoever goes out in search of knowledge is in the cause of Allah until he returns.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(325, "صحيح مسلم", "بلغوا عني ولو آية", "3461", "بلغوا عني ولو آية، وحدثوا عن بني إسرائيل ولا حرج، ومن كذب عليّ متعمداً فليتبوأ مقعده من النار.", "Convey from me even if a single verse, and narrate from Banu Isra'il without blame...", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(326, "سنن الترمذي", "نضّر الله امرأ سمع مقالتي فوعاها فأداها", "2658", "نضّر الله امرأً سمع مقالتي فوعاها وحفظها وبلغها، فرب حامل فقه إلى من هو أفقه منه.", "May Allah brighten the face of a person who hears my words, retains them, and conveys them...", "عن زيد بن ثابت رضي الله عنه"),
        HadithItem(327, "صحيح البخاري", "إن الله لا يقبض العلم انتزاعاً", "100", "إن الله لا يقبض العلم انتزاعاً ينتزعه من العباد، ولكن يقبض العلم بقبض العلماء...", "Allah does not take away knowledge by snatching it from people, but by taking the scholars...", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(328, "صحيح مسلم", "الدال على الخير كفاعله", "1893", "من دل على خير فله مثل أجر فاعله.", "Whoever points to a good deed gets a reward equal to the one who performs it.", "عن أبي مسعود الأنصاري رضي الله عنه"),
        HadithItem(329, "سنن ابن ماجه", "أفضل الصدقة تعلم العلم وتعليه", "243", "أفضل الصدقة أن يتعلم المرء المسلم علماً ثم يعلمه أخاه المسلم.", "The best charity is for a Muslim to learn knowledge then teach it to his Muslim brother.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(330, "صحيح البخاري", "رب حامل فقه غير فقيه", "73", "رب مبلغ أوعى من سامع.", "Perhaps one to whom knowledge is conveyed understands it better than the listener.", "عن أبي بكرة رضي الله عنه"),
        HadithItem(331, "صحيح مسلم", "العلم الذي ينتفع به بعد الموت", "1631", "إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له.", "When a person dies his deeds end except three: ongoing charity, beneficial knowledge, or a righteous child.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(332, "سنن الترمذي", "استغفار الكائنات لمعلم الناس الخير", "2685", "إن الله وملائكته وأهل السماوات والأرض حتى النملة في جحرها وحتى الحوت ليصلون على معلم الناس الخير.", "Allah, His angels, and all in heavens and earth pray for the one who teaches goodness to people.", "عن أبي أمامة الباهلي رضي الله عنه"),
        HadithItem(333, "صحيح البخاري", "لا حسد إلا في اثنتين", "73", "لا حسد إلا في اثنتين: رجل آتاه الله مالاً فسلطه على هلكته في الحق، ورجل آتاه الله الحكمة فهو يقضي بها ويعلمها.", "Envy is not permitted except in two cases: a man given wealth spent in truth, and a man given wisdom...", "عن عبد الله بن مسعود رضي الله عنه"),
        HadithItem(334, "صحيح مسلم", "تعلموا القرآن وعلموه", "804", "تعلموا القرآن واقرؤوه، فإن مثل القرآن لمن تعلمه فقرأه وقام به كمثل جراب محشو مسكاً...", "Learn the Quran and recite it, for the parable of one who learns and recites it is like a bag filled with musk...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(335, "سنن أبي داود", "من كتم علماً ألجمه الله بلجام من نار", "3658", "من سُئل عن علم فكتمه ألجمه الله بلجام من نار يوم القيامة.", "Whoever is asked about knowledge and conceals it, Allah will bridle him with a bridle of fire on Judgment Day.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(336, "صحيح البخاري", "فضل التفقه في الدين", "71", "من يرد الله به خيراً يفقهه في الدين.", "Whomever Allah intends good for, He gives him deep understanding of religion.", "عن معاوية بن أبي سفيان رضي الله عنه"),
        HadithItem(337, "صحيح مسلم", "من دعا إلى هدى كان له من الأجر مثل أجور من تبعه", "2674", "من دعا إلى هدى كان له من الأجر مثل أجور من تبعه لا ينقص ذلك من أجورهم شيئاً...", "Whoever calls to guidance receives reward equal to all who follow him...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(338, "سنن الترمذي", "الحكمة ضالة المؤمن", "2687", "الكلمة الحكمة ضالة المؤمن فحيُث وجدها فهو أحق بها.", "Wisdom is the lost property of the believer; wherever he finds it he is most entitled to it.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(339, "صحيح البخاري", "ليبلغ الشاهد الغائب", "105", "ليبلغ الشاهد الغائب، فإن الشاهد عسى أن يبلغ من هو أوعى له منه.", "Let the present convey to the absent, for the one present may convey to one who understands it better.", "عن أبي بكرة رضي الله عنه"),
        HadithItem(340, "صحيح مسلم", "طلب العلم والعمل الصالح", "2699", "وما اجتمع قوم في بيت من بيوت الله يتلون كتاب الله ويتدارسونه بينهم إلا نزلت عليهم السكينة...", "No group gathers in a house of Allah reciting and studying His Book except tranquility descends upon them...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(341, "صحيح مسلم", "لو يعلم المؤمن ما عند الله من العقوبة", "2755", "لو يعلم المؤمن ما عند الله من العقوبة ما طمع بجنته أحد، ولو يعلم الكافر ما عند الله من الرحمة ما قنط من جنته أحد.", "If the believer knew the full punishment with Allah no one would hope for His Paradise...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(342, "صحيح البخاري", "إن رحمتي سبقت غضبي", "3194", "إن الله لما قضى الخلق كتب عنده فوق عرشه: إن رحمتي سبقت غضبي.", "When Allah created creation He wrote above His Throne: Indeed My mercy overcomes My anger.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(343, "صحيح مسلم", "جعل الله الرحمة مائة جزء", "2752", "جعل الله الرحمة مائة جزء، فأمسك عنده تسعة وتعين جزءاً، وأنزل في الأرض جزءاً واحداً فمن ذلك الجزء تتراحم الخلائق...", "Allah divided mercy into a hundred parts; He kept 99 parts and sent down 1 part to earth...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(344, "سنن الترمذي", "أنا عند ظن عبدي بي", "3603", "يقول الله تعالى: أنا عند ظن عبدي بي، وأنا معه إذا ذكرني...", "Allah says: I am as My servant expects Me to be, and I am with him when he remembers Me.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(345, "صحيح البخاري", "لا يموتن أحدكم إلا وهو يحسن الظن بالله", "6500", "لا يموتن أحدكم إلا وهو يحسن الظن بالله عز وجل.", "Let none of you die except possessing good expectations of Allah Almighty.", "عن جابر بن عبد الله رضي الله عنهما"),
        HadithItem(346, "صحيح مسلم", "عينان لا تمسهما النار", "2745", "عينان لا تمسهما النار: عين بكت من خشية الله، وعين باتت تحرس في سبيل الله.", "Two eyes will not be touched by the Fire: an eye that wept from fear of Allah and an eye guarding in Allah's cause.", "عن عبد الله بن عباس رضي الله عنهما"),
        HadithItem(347, "سنن الترمذي", "لا يلج النار رجل بكى من خشية الله", "1633", "لا يلج النار رجل بكى من خشية الله حتى يعود اللبن في الضَّرْع.", "A man who wept out of fear of Allah will not enter the Fire until milk returns to the udder.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(348, "صحيح البخاري", "الخوف من الشرك والرياء", "6499", "إن أخوف ما أخاف عليكم الشرك الأصغر: الرياء.", "The thing I fear most for you is minor shirk: showing off (Riya).", "عن محمود بن لبيد رضي الله عنه"),
        HadithItem(349, "صحيح مسلم", "وجل القلوب عند ذكر الله", "2823", "المؤمن الذي إذا ذكر الله وجل قلبه وإذا تليت عليه آياته زادته إيماناً.", "The believer is he whose heart trembles when Allah is mentioned, and whose faith increases when His verses are recited.", "عن ابن عباس رضي الله عنهما"),
        HadithItem(350, "سنن الترمذي", "لو خفتم الله حق خيفته لعلمتم العلم الذي لا جهل معه", "2321", "لو تعلمون ما أعلم لضحكتم قليلاً ولبكيتم كثيراً ولخرجتم إلى الصُّعُدات تجأرون إلى الله.", "If you knew what I know, you would laugh little and weep much...", "عن أبي ذر الغفاري رضي الله عنه"),
        HadithItem(351, "صحيح البخاري", "سعة مغفرة الله للتائب", "6308", "يا ابن آدم لو بلغت ذنوبك عنان السماء ثم استغفرتني غفرت لك ولا أبالي.", "O son of Adam, if your sins reached the clouds of the sky and you sought My forgiveness, I would forgive you.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(352, "صحيح مسلم", "يا عبادي إنكم تخطئون بالليل والنهار وأنا أغفر الذنوب جميعاً", "2577", "يا عبادي إنكم تخطئون بالليل والنهار وأنا أغفر الذنوب جميعاً فاستغفروني أغفر لكم.", "O My servants, you commit sins night and day, and I forgive all sins, so seek My forgiveness...", "عن أبي ذر الغفاري رضي الله عنه"),
        HadithItem(353, "سنن الترمذي", "من خاف أدلج ومن أدلج بلغ المنزل", "2450", "من خاف أدلج، ومن أدلج بلغ المنزل، ألا إن سلعة الله غالية، ألا إن سلعة الله الجنة.", "He who fears sets out at night, and he who sets out early reaches home; Allah's merchandise is valuable: Paradise.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(354, "صحيح البخاري", "فضل الخوف والرجاء في قلب المؤمن", "6469", "دخل النبي على شاب وهو في الموت فقال: كيف تجدك؟ قال: أرجو الله وأخاف ذنوبي، فقال: لا يجتمعان في قلب عبد في مثل هذا الموطن إلا أعطاه الله ما يرجو وآمنه مما يخاف.", "The Prophet visited a dying youth who said: I hope in Allah and fear my sins. He said: Both combine only to grant hope and safety.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(355, "صحيح مسلم", "إن الله لا يظلم مؤمناً حسنة", "2808", "إن الله لا يظلم مؤمناً حسنة يُعطى بها في الدنيا ويُجزى بها في الآخرة.", "Allah does not wrong a believer regarding a good deed: he is rewarded for it in this world and the Hereafter.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(356, "صحيح البخاري", "من أحب لقاء الله أحب الله لقاءه", "6507", "من أحب لقاء الله أحب الله لقاءه ومن كره لقاء الله كره الله لقاءه.", "Whoever loves to meet Allah, Allah loves to meet him, and whoever hates to meet Allah, Allah hates to meet him.", "عن عائشة أم المؤمنين رضي الله عنها"),
        HadithItem(357, "صحيح مسلم", "بشروا ولا تنفروا", "1732", "بشروا ولا تنفروا ويسروا ولا تعسروا.", "Give good tidings and do not repel, make things easy and do not make them hard.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(358, "سنن الترمذي", "إن عظم الجزاء مع عظم البلاء", "2396", "إذا أراد الله بعبده الخير عجل له العقوبة في الدنيا، وإذا أراد بعبده الشر أمسك عنه بذنبه حتى يوافي به يوم القيامة.", "When Allah intends good for a servant He hastens punishment in this world...", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(359, "صحيح البخاري", "حسن الظن بالله عند الموت", "6501", "أنا عند ظن عبدي بي فلْيظن بي ماشاء.", "I am as My servant expects Me to be, so let him expect of Me as he wishes.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(360, "صحيح مسلم", "ورحمتي وسعت كل شيء", "2751", "إن الله كتب كتاباً قبل أن يخلق الخلق: إن رحمتي سبقت غضبي فهو مكتوب عنده فوق العرش.", "Allah ordained before creating creation: Indeed My mercy prevails over My wrath.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(361, "صحيح مسلم", "أين المتحابون بجلالي اليوم أظلهم في ظلي", "2566", "إن الله يقول يوم القيامة: أين المتحابون بجلالي؟ اليوم أظلهم في ظلي يوم لا ظل إلا ظلي.", "Allah says on Resurrection Day: Where are those who loved each other for My Majesty? Today I shade them...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(362, "متفق عليه", "ثلاث من كن فيه وجد حلاوة الإيمان", "16", "أن يكون الله ورسوله أحب إليه مما سواهما وأن يحب المرء لا يحبه إلا لله...", "Three qualities: loving Allah and His Messenger above all, and loving a person solely for Allah...", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(363, "سنن الترمذي", "المتحابون في الله على منابر من نور", "2390", "المتحابون في جلالي لهم منابر من نور يغبطهم النبيون والشهداء.", "Those who love each other for My Majesty will have pulpits of light envied by Prophets and martyrs.", "عن معاذ بن جبل رضي الله عنه"),
        HadithItem(364, "صحيح مسلم", "زار أخاً له في قرية أخرى أرسل الله له ملكاً", "2567", "أن رجلاً زار أخاً له في قرية أخرى فأرصد الله له على مدرجته ملكاً... فقال: إن الله قد أحبك كما أحببته فيه.", "A man visited his brother in another village; Allah sent an angel saying: Allah loves you as you loved him.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(365, "صحيح البخاري", "المرء مع من أحب", "6168", "جاء رجل إلى النبي فقال: متى الساعة؟ قال: وما أعددت لها؟ قال: لا شيء إلا أني أحب الله ورسوله. قال: أنت مع من أحببت.", "A man asked about the Hour; the Prophet asked: What prepared? He said: Love for Allah and Messenger. He said: You are with whom you love.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(366, "سنن أبي داود", "إذا أحب أحدكم أخاه فليخبره", "5124", "إذا أحب أحدكم أخاه فليخبره أنه يحبه.", "When one of you loves his brother, let him inform him that he loves him.", "عن المقدام بن معديكرب رضي الله عنه"),
        HadithItem(367, "صحيح مسلم", "تهادوا تحابوا", "2568", "تهادوا تحابوا.", "Exchange gifts and you will love one another.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(368, "صحيح البخاري", "مثل المؤمنين في تراحمهم وتوادهم", "6011", "مثل المؤمنين في تراحمهم وتوادهم وتعاطفهم كمثل الجسد إذا اشتكى منه عضو تداعى له سائر الجسد بالسهر والحمى.", "The parable of believers in mutual affection and mercy is like a single body...", "عن النعمان بن بشير رضي الله عنه"),
        HadithItem(369, "صحيح مسلم", "المؤمن للمؤمن كالبنيان يشد بعضه بعضاً", "2585", "المؤمن للمؤمن كالبنيان يشد بعضه بعضاً وشبك بين أتابعه.", "A believer to another believer is like a building whose parts reinforce each other.", "عن أبي موسى الأشعري رضي الله عنه"),
        HadithItem(370, "سنن الترمذي", "أوثق عرى الإيمان الحب في الله والبغض في الله", "2521", "أوثق عرى الإيمان: الحب في الله والبغض في الله.", "The firmest handhold of faith is loving for Allah and hating for Allah.", "عن البراء بن عازب رضي الله عنه"),
        HadithItem(371, "صحيح البخاري", "لا تحاسدوا ولا تباغضوا وكونوا عباد الله إخواناً", "6065", "لا تحاسدوا ولا تباغضوا ولا تدابروا وكونوا عباد الله إخواناً المسلم أخو المسلم لا يظلمه ولا يسلمه...", "Do not envy, hate, or turn away from each other; be servants of Allah as brothers...", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(372, "صحيح مسلم", "المسلم أخو المسلم لا يظلمه ولا يحقره", "2564", "المسلم أخو المسلم لا يظلمه ولا يخذله ولا يحقره، بحسب امرئ من الشر أن يحقر أخاه المسلم.", "A Muslim is a brother to a Muslim: he does not wrong, abandon, or despise him...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(373, "سنن الترمذي", "أحب الحبيب هوناً ما عسى أن يكون بغيضك يوماً ما", "1997", "أحبب حبيبك هوناً ما عسى أن يكون بغيضك يوماً ما، وأبغض بغيضك هوناً ما عسى أن يكون حبيبك يوماً ما.", "Love your beloved moderately for he may become hated one day, and hate moderately...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(374, "صحيح البخاري", "سبعة يظلهم الله منهم رجلان تحابا في الله", "1423", "ورجلان تحابا في الله اجتماعا عليه وتفرقا عليه.", "And two men who loved each other for Allah's sake, meeting and parting upon it.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(375, "صحيح مسلم", "حق المسلم على المسلم إذا لقيته فسلم عليه", "2162", "حق المسلم على المسلم ست: إذا لقيته فسلم عليه، وإذا دعاك فأجبه، وإذا استنصحك فانصح له...", "Six rights of a Muslim over another: greet when meeting, accept invitation, give advice when asked...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(376, "سنن أبي داود", "ما تصافح مسلمان إلا غفر لهما قبل أن يفترقا", "5212", "ما من مسلمين يلتقيان فيتصافحان إلا غُفر لهما قبل أن يفترقا.", "No two Muslims meet and shake hands except that they are forgiven before they part.", "عن البراء بن عازب رضي الله عنه"),
        HadithItem(377, "صحيح البخاري", "إياكم والظن والهجران", "6066", "إياكم والظن فإن الظن أكذب الحديث، ولا تحسسوا ولا تجسسوا ولا تنافسوا ولا تحاسدوا...", "Beware of suspicion, spying, competing, and envying each other; be brothers.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(378, "صحيح مسلم", "خير الأصحاب عند الله خيرهم لصاحبه", "2568", "خير الأصحاب عند الله خيرهم لصاحبه.", "The best of companions to Allah is the best to his companion.", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(379, "سنن الترمذي", "لا تصاحب إلا مؤمناً ولا يأكل طعامك إلا تقي", "2395", "لا تصاحب إلا مؤمناً ولا يأكل طعامك إلا تقي.", "Do not keep company except with a believer, and let none eat your food except the pious.", "عن أبي سعيد الخدري رضي الله عنه"),
        HadithItem(380, "صحيح البخاري", "مثل الجليس الصالح والجليس السوء", "2101", "مثل الجليس الصالح والجليس السوء كحامل المسك ونافخ الكير...", "The parable of good and bad companion is like the musk seller and the blacksmith bellows...", "عن أبي موسى الأشعري رضي الله عنه"),
        HadithItem(381, "صحيح مسلم", "الحمد لله تملأ الميزان", "223", "الطهور شطر الإيمان والحمد لله تملأ الميزان وسبحان الله والحمد لله تملآن ما بين السماوات والأرض.", "Purity is half of faith, Alhamdulillah fills the scale, SubhanAllah and Alhamdulillah fill heaven and earth.", "عن أبي مالك الأشعري رضي الله عنه"),
        HadithItem(382, "صحيح البخاري", "من لم يشكر الناس لم يشكر الله", "2182", "لا يشكر الله من لا يشكر الناس.", "He does not thank Allah who does not thank people.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(383, "سنن الترمذي", "التحدث بنعم الله شكر وتركها كفر", "1955", "التحدث بنعمة الله شكر وتركها كفر، ومن لا يشكر القليل لا يشكر الكثير.", "Speaking of Allah's favors is gratitude, leaving it is ingratitude; who thanks not for little thanks not for much.", "عن النعمان بن بشير رضي الله عنه"),
        HadithItem(384, "صحيح مسلم", "انظروا إلى من هو أسفل منكم ولا تنظروا إلى من هو فوقكم", "2963", "انظروا إلى من هو أسفل منكم ولا تنظروا إلى من هو فوقكم فهو أجدر أن لا تزدروا نعمة الله عليكم.", "Look at those below you and not at those above you; it is more fitting so you do not belittle Allah's favor.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(385, "صحيح البخاري", "من أصبح منكم آمناً في سربه معافى في جسده", "2346", "من أصبح منكم آمناً في سربه معافى في جسده عنده قوت يومه فكأنما حيزت له الدنيا بحذافيرها.", "Whoever among you wakes up secure in his dwelling, healthy in body, having food for the day...", "عن عبيد الله بن محصن رضي الله عنه"),
        HadithItem(386, "سنن الترمذي", "اللهم اجعلني شكوراً واجعلني صبوراً", "3561", "اللهم اجعلني شكوراً، واجعلني صبوراً، واجعلني في عيني صغيراً وفي أعين الناس كبيراً.", "O Allah make me deeply grateful, patient, small in my own eyes, and respected in people's eyes.", "عن بريدة بن الحصيب رضي الله عنه"),
        HadithItem(387, "صحيح مسلم", "عجباً لأمر المؤمن إن أمره كله خير", "2999", "إن أصابته سراء شكر فكان خيراً له وإن أصابته ضراء صبر فكان خيراً له.", "If ease touches him he is grateful and it is good, if harm touches him he is patient and it is good.", "عن صهيب بن سنان رضي الله عنه"),
        HadithItem(388, "صحيح البخاري", "كان النبي إذا رَأَى ما يُحِبّ قال الحمد لله الذي بنعمته تتم الصالحات", "5411", "كان النبي إذا رأى ما يحب قال: الحمد لله الذي بنعمته تتم الصالحات، وإذا رأى ما يكره قال: الحمد لله على كل حال.", "When seeing what he liked he said 'Praise Allah by Whose grace good deeds complete', otherwise 'Praise Allah in all states'.", "عن عائشة أم المؤمنين رضي الله عنها"),
        HadithItem(389, "سنن أبي داود", "دعاء سيد الاستغفار والشكر", "5074", "اللهم ما أصبح بي من نعمة أو بأحد من خلقك فمنك وحدك لا شريك لك فلك الحمد ولك الشكر.", "O Allah, whatever favor reaches me or any creature this morning is from You alone...", "عن عبد الله بن غنام رضي الله عنه"),
        HadithItem(390, "صحيح مسلم", "الطاعم الشاكر كالصائم الصابر", "2018", "الطاعم الشاكر بمنزلة الصائم الصابر.", "The grateful eater is in the position of the patient fasting person.", "عن سنان بن سنة رضي الله عنه"),
        HadithItem(391, "صحيح البخاري", "إذا نظر أحدكم إلى من فُضِّل عليه في المال والخلْق فلينظر إلى من هو أسفل منه", "6490", "إذا نظر أحدكم إلى من فُضِّل عليه في المال والخلْق فلينظر إلى من هو أسفل منه ممن فُضِّل عليه.", "When one of you sees someone favored over him in wealth and physique, let him look at one below him.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(392, "سنن الترمذي", "أفضل العبادة انتظار الفرج والشكر", "3571", "أفضل العبادة انتظار الفرج.", "The best worship is expecting relief from Allah with gratitude.", "عن عبد الله بن مسعود رضي الله عنه"),
        HadithItem(393, "صحيح مسلم", "رضيت بالله رباً وبالإسلام ديناً وبمحمد رسولاً", "386", "من قال إذا سمع المؤذن: رضيت بالله رباً وبالإسلام ديناً وبمحمد رسولاً غُفر له ذنبه.", "Whoever says upon hearing the Adhan 'I am pleased with Allah as Lord...' his sins are forgiven.", "عن سعد بن أبي وقاص رضي الله عنه"),
        HadithItem(394, "صحيح البخاري", "الدعاء بالبركة والشكر على الطعام", "5458", "إذا رفعت المائدة قال: الحمد لله حمداً كثيراً طيباً مباركاً فيه غير مكفي ولا ودّع ولا مستغنى عنه ربنا.", "When the food mat was raised he said: Abundant, pure, blessed praise be to Allah...", "عن أبي أمامة الباهلي رضي الله عنه"),
        HadithItem(395, "سنن الترمذي", "ما أنعم الله على عبد نعمة فقال الحمد لله إلا كان الذي أعطى أفضل مما أخذ", "2738", "ما أنعم الله على عبد نعمة فقال: الحمد لله إلا كان الذي أعطى أفضل مما أخذ.", "No servant is granted a favor and says Alhamdulillah except that what he gave (praise) is better than what he took.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(396, "صحيح مسلم", "أول من يدعى إلى الجنة يوم القيامة الحمادون", "223", "أول من يُدعى إلى الجنة يوم القيامة الحمّادون الذين يحمدون الله في السراء والضراء.", "The first to be invited to Paradise on Judgment Day are those who constantly praise Allah in ease and hardship.", "عن ابن عباس رضي الله عنهما"),
        HadithItem(397, "صحيح البخاري", "القناعة كنز لا يفنى والرضا غنى النفس", "6446", "ليس الغنى عن كثرة العرَض ولكن الغنى غنى النفس.", "Richness is not having many possessions, but true richness is the richness of the soul.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(398, "سنن أبي داود", "اللهم أعرني على ذكرك وشكرك وحسن عبادتك", "1522", "يا معاذ والله إني لأحبك، فلا تدعن في دبر كل صلاة تقول: اللهم أعني على ذكرك وشكرك وحسن عبادتك.", "O Mu'adh, by Allah I love you; do not fail to say after every prayer: O Allah help me remember You, thank You...", "عن معاذ بن جبل رضي الله عنه"),
        HadithItem(399, "صحيح مسلم", "الرضا بقضاء الله وقدره", "2664", "احرص على ما ينفعك واستعن بالله ولا تعجز، وإن أصابك شيء قل: قدر الله وما شاء فعل.", "Strive for what benefits you, seek Allah's help, do not give up, and if anything befalls say: Allah decreed...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(400, "متفق عليه", "خاتمة الموسوعة الشريفة والثناء على الله", "6406", "كلمتان خفيفتان على اللسان، ثقيلتان في الميزان، حبيبتان إلى الرحمن: سبحان الله وبحمده، سبحان الله العظيم.", "Two phrases are light on the tongue, heavy on the scales, beloved to the Most Merciful: SubhanAllah wa bihamdihi, SubhanAllah al-Azim.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(401, "صحيح البخاري", "القناعة والغنى الحقيقي", "6446", "ليس الغنى عن كثرة العرض، ولكن الغنى غنى النفس.", "Richness is not in having many possessions, but true richness is the richness of the soul.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(402, "صحيح مسلم", "الفلاح بالقناعة", "1054", "قد أفلح من أسلم، ورُزق كفافاً، وقنّعه الله بما آتاه.", "He has succeeded who accepts Islam, is provided with sufficient sustenance, and Allah makes him content.", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(403, "صحيح مسلم", "النظر إلى من هو أسفل", "2963", "انظروا إلى من هو أسفل منكم، ولا تنظروا إلى من هو فوقكم، فهو أجدر أن لا تزدروا نعمة الله عليكم.", "Look at those beneath you and not those above you, so you do not underestimate Allah's blessing.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(404, "صحيح البخاري", "ابن آدم وطلب المال", "6439", "لو كان لابن آدم وادٍ من ذهب أحب أن يكون له واديان، ولن يملأ فاه إلا التراب، ويتوب الله على من تاب.", "If the son of Adam had a valley of gold, he would desire two, and nothing fills his mouth except dust.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(405, "سنن ابن ماجه", "الزهد ومحبة الله والناس", "4102", "ازهد في الدنيا يحبك الله، وازهد فيما في أيدي الناس يحبك الناس.", "Be indifferent towards the world and Allah will love you, and be indifferent to what people have.", "عن سهل بن سعد الساعدي رضي الله عنه"),
        HadithItem(406, "سنن الترمذي", "حيازة الدنيا بالأمن والعافية", "2346", "من أصبح منكم آمناً في سربه، معافى في جسده، عنده قوت يومه، فكأنما حيزت له الدنيا بحذافيرها.", "Whoever wakes up secure, healthy, having food for the day, it is as if the whole world was given to him.", "عن عبيد الله بن محصن رضي الله عنه"),
        HadithItem(407, "مسند أحمد", "ما قل وكفى", "21721", "ما قل وكفى خير مما كثر وألهى.", "What is small but sufficient is better than what is plentiful but distracting.", "عن أبي الدرداء رضي الله عنه"),
        HadithItem(408, "سنن الترمذي", "الاعتدال في الطعام", "2380", "ما ملأ أدمي وعاءً شراً من بطن، بحسب ابن آدم أكلات يقمن صلبه.", "No human fills a vessel worse than his stomach. A few mouthfuls are enough to keep his spine straight.", "عن المقدام بن معد يكرب رضي الله عنه"),
        HadithItem(409, "صحيح البخاري", "شكر النعمة", "6437", "إذا نظر أحدكم إلى من فُضّل عليه في المال والخلق، فلينظر إلى من هو أسفل منه.", "When one of you looks at someone favored in wealth and form, let him look at someone beneath him.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(410, "صحيح البخاري", "البركة في الطعام", "5392", "طعام الاثنين كافي الثلاثة، وطعام الثلاثة كافي الأربعة.", "The food of two is sufficient for three, and the food of three is sufficient for four.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(411, "صحيح مسلم", "دعاء الكفاف", "1055", "اللهم اجعل رزق آل محمد كفافاً.", "O Allah, make the provision of the family of Muhammad sufficient for basic needs.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(412, "صحيح مسلم", "الجمال والكبر", "91", "إن الله جميل يحب الجمال، الكبر بَطَر الحق وغَمْط الناس.", "Allah is Beautiful and loves beauty. Arrogance is refusing the truth and despising people.", "عن عبد الله بن مسعود رضي الله عنه"),
        HadithItem(413, "صحيح مسلم", "حمد الله على النعم", "2734", "إن الله ليرضى عن العبد أن يأكل الأكلة فيحمده عليها، أو يشرب الشربة فيحمده عليها.", "Allah is pleased with the servant who eats a meal and praises Him for it.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(414, "سنن الترمذي", "زاد الراكب", "2377", "إذا أردتِ اللحوق بي فليكفكِ من الدنيا كزاد الراكب، وإياكِ ومجالسة الأغنياء.", "If you wish to join me, let what suffices you of this world be like the provisions of a rider.", "عن عائشة رضي الله عنها"),
        HadithItem(415, "صحيح البخاري", "عطاء الصبر", "1469", "من يتصبر يصبره الله، وما أُعطي أحد عطاءً خيراً وأوسع من الصبر.", "Whoever seeks patience, Allah will grant him patience. No gift is better and wider than patience.", "عن أبي سعيد الخدري رضي الله عنه"),
        HadithItem(416, "مسند أحمد", "صلاح الأمة بالزهد", "13320", "إن صلاح أول هذه الأمة بالزهد واليقين، ويهلك آخرها بالبخل والأمل.", "The righteousness of the first part of this nation came through asceticism and certainty.", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(417, "صحيح البخاري", "الغربة في الدنيا", "6416", "كن في الدنيا كأنك غريب أو عابر سبيل.", "Be in this world as though you were a stranger or a traveler along a path.", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(418, "صحيح مسلم", "حقيقة الدنيا للمؤمن", "2956", "الدنيا سجن المؤمن وجنة الكافر.", "The world is a prison for the believer and a paradise for the disbeliever.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(419, "صحيح مسلم", "العمل بعد الموت", "1631", "إذا مات الإنسان انقطع عنه عمله إلا من ثلاثة: إلا من صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له.", "When a human dies, his deeds end except for three: ongoing charity, beneficial knowledge, or a child praying.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(420, "صحيح مسلم", "الدال على الخير", "1893", "من دلّ على خير فله مثل أجر فاعله.", "Whoever guides to good will have a reward like the one who does it.", "عن أبي مسعود الأنصاري رضي الله عنه"),
        HadithItem(421, "صحيح مسلم", "مقام العادلين عند الله", "1827", "إن المقسطين عند الله على منابر من نور عن يمين الرحمن، الذين يعدلون في حكمهم وأهليهم وما ولوا.", "Those who are just will be with Allah upon pulpits of light on the right hand of the Most Merciful.", "عن عبد الله بن عمرو رضي الله عنهما"),
        HadithItem(422, "صحيح البخاري", "الإمام العادل في ظل العرش", "660", "سبعة يظلهم الله في ظله يوم لا ظل إلا ظله: إمام عادل...", "Seven whom Allah will shade in His shade on the Day when there is no shade but His: a just leader...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(423, "سنن أبي داود", "ترافُق المسلمين وعدلهم", "2751", "المسلمون تَتَكَافَأُ دِمَاؤُهُمْ، وَيَسْعَى بِذِمَّتِهِمْ أَدْنَاهُمْ، وَهُمْ يَدٌ عَلَى مَنْ سِوَاهُمْ.", "The lives of Muslims are equal, and the protection granted by the humblest is binding on all.", "عن علي بن أبي طالب رضي الله عنه"),
        HadithItem(424, "سنن الترمذي", "أداء الأمانة والوفاء", "1264", "أدِّ الأمانة إلى من ائتمنك، ولا تخن من خانك.", "Fulfill the trust to the one who trusted you, and do not betray the one who betrayed you.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(425, "صحيح البخاري", "علامة المنافق في الخيانة", "33", "آية المنافق ثلاث: إذا حدث كذب، وإذا وعد أخلف، وإذا اؤتمن خان.", "The signs of a hypocrite are three: when he speaks he lies, when he promises he breaks it, when trusted he betrays.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(426, "صحيح مسلم", "أداء الحقوق يوم القيامة", "2582", "لتؤدن الحقوق إلى أهلها يوم القيامة، حتى يقاد للشاة الجلجاء من الشاة القرناء.", "Rights will surely be restored to their owners on Judgment Day, even between hornless and horned sheep.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(427, "صحيح مسلم", "تحريم الظلم بين العباد", "2577", "يا عبادي إني حرمت الظلم على نفسي وجعلته بينكم محرماً فلا تظالموا.", "O My servants, I have forbidden injustice for Myself and made it forbidden among you, so do not wrong one another.", "عن أبي ذر الغفاري رضي الله عنه"),
        HadithItem(428, "صحيح مسلم", "الظلم ظلمات يوم القيامة", "2578", "اتقوا الظلم، فإن الظلم ظلمات يوم القيامة، واتقوا الشح فإن الشح أهلك من كان قبلكم.", "Beware of injustice, for injustice is darknesses on the Day of Resurrection.", "عن جابر بن عبد الله رضي الله عنهما"),
        HadithItem(429, "صحيح مسلم", "عقوبة اقتطاع حق المسلم", "137", "من اقتطع حق امرئ مسلم بيمينه فقد أوجب الله له النار وحرم عليه الجنة.", "Whoever deprives a Muslim of his right through a false oath, Allah obligates the Fire for him.", "عن أبي أمامة الحارثي رضي الله عنه"),
        HadithItem(430, "مستدرك الحاكم", "الأمانة في الولايات", "7022", "من وُلّي من أمر المسلمين شيئاً فاستعمل عليهم أحداً محاباةً فعليه لعنة الله.", "Whoever is in charge of Muslims' affairs and appoints someone out of favoritism, upon him is Allah's curse.", "عن ابن عباس رضي الله عنهما"),
        HadithItem(431, "سنن أبي داود", "أنواع القضاة والعدل", "3573", "القضاة ثلاثة: واحد في الجنة واثنان في النار؛ فأما الذي في الجنة فرجل عرف الحق وقضى به.", "Judges are three types: one in Paradise who recognized the truth and judged accordingly, and two in the Fire.", "عن بريدة بن الحصيب رضي الله عنه"),
        HadithItem(432, "سنن أبي داود", "خطورة شهادة الزور", "2873", "من شهد شهادة زور عُدلت بالإشراك بالله.", "Whoever gives false testimony, it is made equivalent to associating partners with Allah.", "عن خريم بن فاتك رضي الله عنه"),
        HadithItem(433, "مسند أحمد", "الأمانة والعهد في الدين", "12383", "لا إيمان لمن لا أمانة له، ولا دين لمن لا عهد له.", "There is no complete faith for one who has no trustworthiness, and no religion for one who keeps no covenant.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(434, "صحيح البخاري", "السماحة في البيع والشراء", "2076", "رحم الله رجلاً سمحاً إذا باع، وإذا اشتري، وإذا اقتضى.", "May Allah show mercy to a man who is easygoing when he sells, when he buys, and when he demands his due.", "عن جابر بن عبد الله رضي الله عنهما"),
        HadithItem(435, "سنن أبي داود", "عقوبة التهمة والبهتان", "3597", "من قال في مؤمن ما ليس فيه، أسكنه الله رداغة الخبال حتى يخرج مما قال.", "Whoever says about a believer what is not in him, Allah will lodge him in destruction until he retracts.", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(436, "مسند أحمد", "حرمة مال المسلم", "20695", "لا يحل لامرئ أن يأخذ عصا أخيه بغير طيب نفس منه.", "It is not permissible for a person to take even a stick belonging to his brother without his consent.", "عن أخي أبي قتادة رضي الله عنه"),
        HadithItem(437, "سنن ابن ماجه", "أداء أجر الأجير", "2443", "أعطوا الأجير أجره قبل أن يجف عرقه.", "Give the hired worker his wages before his sweat dries.", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(438, "صحيح مسلم", "تحريم الغش والتحايل", "101", "من غشنا فليس منا.", "Whoever cheats us is not of us.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(439, "صحيح البخاري", "دعوة المظلوم المستجابة", "2448", "اتق دعوة المظلوم، فإنها ليس بينها وبين الله حجاب.", "Beware the supplication of the oppressed, for there is no barrier between it and Allah.", "عن ابن عباس رضي الله عنهما"),
        HadithItem(440, "صحيح البخاري", "نصر الأخ الظالم والمظلوم", "2444", "انصر أخاك ظالماً أو مظلوماً. قيل: كيف ننصره ظالماً؟ قال: تحجزه أو تمنعه من الظلم فإن ذلك نصره.", "Help your brother whether oppressor or oppressed. Prevent him from oppression; that is helping him.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(441, "صحيح البخاري", "تكفير الذنوب بالبلاء", "5641", "ما يصيب المسلم من نصب ولا وصب ولا هم ولا حزن ولا أذى ولا غم حتى الشوكة يشاكها إلا كفر الله بها من خطاياه.", "No fatigue, disease, anxiety, or harm befalls a Muslim, even a thorn prick, but Allah expiates his sins thereby.", "عن أبي سعيد وأبي هريرة رضي الله عنهما"),
        HadithItem(442, "صحيح البخاري", "الصبر عند الصدمة الأولى", "1283", "إنما الصبر عند الصدمة الأولى.", "True patience is only displayed at the first stroke of a calamity.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(443, "صحيح البخاري", "من يرد الله به خيراً يصب منه", "5645", "من يرد الله به خيراً يصب منه.", "Whomever Allah intends good for, He subjects him to trials.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(444, "سنن الترمذي", "ابتلاء الله لمن يحبهم", "2396", "إذا أحب الله قوماً ابتلاهم، فمن رضي فله الرضا، ومن سخط فله السخط.", "When Allah loves a people, He tests them. Whoever is content receives contentment.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(445, "سنن الترمذي", "عظم الجزاء مع عظم البلاء", "2396", "عظم الجزاء مع عظم البلاء، وإن الله إذا أحب قوماً ابتلاهم.", "The magnitude of reward goes along with the magnitude of trial.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(446, "سنن الترمذي", "استمرار البلاء ومحو الذنوب", "2399", "ما يزال البلاء بالمؤمن والمؤمنة في نفسه وولده وماله حتى يلقى الله وما عليه خطيئة.", "Trials will continue to befall believing men and women until they meet Allah with no sin.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(447, "سنن الترمذي", "شدة بلاء الأنبياء والصالحين", "2398", "أشد الناس بلاءً الأنبياء، ثم الأمثل فالأمثل، يُبتلى الرجل على حسب دينه.", "The most severely tested people are the Prophets, then those closest to them.", "عن سعد بن أبي وقاص رضي الله عنه"),
        HadithItem(448, "صحيح مسلم", "دعاء المصيبة والأجر", "918", "ما من مسلم تصيبه مصيبة فيقول: إنا لله وإنا إليه راجعون، اللهم أجرني في مصيبتي وأخلف لي خيراً منها، إلا أخلف الله له خيراً منها.", "No Muslim is afflicted with a calamity and prays for Allah's reward except Allah replaces it with better.", "عن أم سلمة رضي الله عنها"),
        HadithItem(449, "صحيح البخاري", "جزاء الصبر على فقد الحبيب", "6424", "يقول الله تعالى: ما لعبدي المؤمن عندي جزاءٌ إذا قبضتُ صفيَّه من أهل الدنيا ثم احتسبه إلا الجنة.", "Allah says: I have no reward for My servant when I take his beloved and he seeks reward except Paradise.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(450, "صحيح البخاري", "أجر المريض والمسافر", "2996", "إذا مرض العبد أو سافر كُتب له مثل ما كان يعمل مقيماً صحيحاً.", "When a servant falls ill or travels, there is written for him what he used to do when healthy and resident.", "عن أبي موسى الأشعري رضي الله عنه"),
        HadithItem(451, "صحيح البخاري", "الصبر على فقد البصر", "5653", "إن الله قال: إذا ابتليت عبدي بحبيبتيه فصبر، عوضته منهما الجنة.", "Allah said: If I test My servant with his two eyes and he is patient, I compensate him with Paradise.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(452, "صحيح البخاري", "مثل المؤمن والزرع في البلاء", "5644", "مثل المؤمن كمثل الخامة من الزرع، تفيؤها الريح صرعاً وتعدلها أخرى حتى تأتيه أجله.", "The example of a believer is like a fresh tender plant; the wind bends it and straightens it until death.", "عن كعب بن مالك رضي الله عنه"),
        HadithItem(453, "صحيح البخاري", "الشديد من يملك نفسه عند الغضب", "6114", "ليس الشديد بالصُّرَعَةِ، إنما الشديد الذي يملك نفسه عند الغضب.", "The strong man is not the good wrestler, but the one who controls himself in anger.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(454, "مسند أحمد", "السكوت عند الغضب", "2136", "إذا غضب أحدكم فليصمت.", "If one of you becomes angry, let him remain silent.", "عن عبد الله بن عباس رضي الله عنهما"),
        HadithItem(455, "سنن أبي داود", "تغيير الهيئة عند الغضب", "4782", "إذا غضب أحدكم وهو قائم فليجلس، فإن ذهب عنه الغضب وإلا فليضطجع.", "If one of you becomes angry while standing, let him sit down; if anger leaves him, fine, else lie down.", "عن أبي ذر الغفاري رضي الله عنه"),
        HadithItem(456, "سنن ابن ماجه", "فضل كظم الغيظ", "4189", "ما غَصّ عبدٌ غصةً أحبّ إلى الله من غصة غيظ كظمها ابتغاء وجه الله.", "No servant swallowed a gulp more beloved to Allah than a gulp of rage swallowed seeking Allah's pleasure.", "عن ابن عمر رضي الله عنهما"),
        HadithItem(457, "سنن الترمذي", "أجر كظم الغيظ يوم القيامة", "2021", "من كظم غيظاً وهو قادر على أن ينفذه، دعاه الله على رؤوس الخلائق يوم القيامة حتى يخيره من أي الحور شاء.", "Whoever suppresses anger when capable of acting, Allah will honor him before all creation on Judgment Day.", "عن معاذ بن أنس رضي الله عنه"),
        HadithItem(458, "صحيح البخاري", "تحريم الهجران بين المسلمين", "6077", "لا يحل لمسلم أن يهجر أخاه فوق ثلاث ليالٍ، يلتقيان فيعرض هذا ويعرض هذا، وخيرهما الذي يبدأ بالسلام.", "It is not lawful for a Muslim to abandon his brother for more than three nights...", "عن أبي أيوب الأنصاري رضي الله عنه"),
        HadithItem(459, "صحيح مسلم", "مغفرة الذنوب يوم الاثنين والخميس", "2565", "تُفتح أبواب الجنة يوم الاثنين ويوم الخميس، فيُغفر لكل عبد لا يشرك بالله شيئاً إلا رجلاً كانت بينه وبين أخيه شحناء.", "The gates of Paradise open Mondays and Thursdays, forgiving every believer except those with malice.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(460, "مسند أحمد", "مكارم الأخلاق الثلاث", "17452", "صِلْ مَنْ قَطَعَكَ، وَأَعْطِ مَنْ حَرَمَكَ، وَاعْفُ عَمَّنْ ظَلَمَكَ.", "Keep ties with whoever cuts you off, give to whoever deprives you, and pardon whoever wrongs you.", "عن عقبة بن عامر رضي الله عنه"),
        HadithItem(461, "صحيح البخاري", "فضل الأكل من عمل اليد", "2072", "ما أكل أحد طعاماً قط خيراً من أن يأكل من عمل يده، وإن نبي الله داود عليه السلام كان يأكل من عمل يده.", "No one has eaten better food than that earned by the work of his own hands.", "عن المقدام بن معد يكرب رضي الله عنه"),
        HadithItem(462, "صحيح البخاري", "الاستغناء بالعمل عن المسألة", "1471", "لأن يأخذ أحدكم حَبْلَهُ فيأتي بحزمة حطب على ظهره فيبيعه فيكف به وجهه خير له من أن يسأل الناس.", "For one of you to take his rope and bring firewood on his back is better than asking people.", "عن الزبير بن العوام رضي الله عنه"),
        HadithItem(463, "سنن الترمذي", "منزلة التاجر الأمين", "1209", "التَّاجِرُ الصَّدُوقُ الأَمِينُ مَعَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ.", "The truthful and trustworthy merchant will be with Prophets, truthful ones, and martyrs.", "عن أبي سعيد الخدري رضي الله عنه"),
        HadithItem(464, "المعجم الأوسط", "طلب الحلال جهاد", "8610", "طلب الحلال جهاد، وإن الله يحب العبد المحترف.", "Seeking halal earnings is a struggle, and Allah loves the skilled worker.", "عن ابن عباس رضي الله عنهما"),
        HadithItem(465, "صحيح مسلم", "إن الله طيب لا يقبل إلا طيباً", "1015", "إن الله طيب لا يقبل إلا طيباً، وإن الله أمر المؤمنين بما أمر به المرسلين.", "Allah is Pure and accepts only that which is pure.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(466, "سنن الترمذي", "خطورة المال الحرام", "614", "كل جسد نبت من سحت فالنار أولى به.", "Any body nourished by unlawful earnings, the Fire is more deserving of it.", "عن كعب بن عجرة رضي الله عنه"),
        HadithItem(467, "صحيح البخاري", "زمان لا يبالي المرء بالحرام", "2083", "ليأتين على الناس زمان لا يبالي المرء بما أخذ المال، أمن حلال أم من حرام.", "A time will come when a person will not care whether money was gained from halal or haram.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(468, "سنن الترمذي", "ترك الشبهات والورع", "2518", "دع ما يريبك إلى ما لا يريبك، فإن الصدق طمأنينة والكذب ريبة.", "Leave that which makes you doubtful for that which does not make you doubtful.", "عن الحسن بن علي رضي الله عنهما"),
        HadithItem(469, "صحيح البخاري", "الحلال بين والحرام بين", "52", "إن الحلال بين وإن الحرام بين وبينهما أمور مشتبهات لا يعلمهن كثير من الناس، فمن اتقى الشبهات فقد استبرأ لدينه وعرضه.", "The halal is clear and the haram is clear, and between them are doubtful matters.", "عن النعمان بن بشير رضي الله عنهما"),
        HadithItem(470, "صحيح مسلم", "أخوة المسلم وحرمة ماله", "2564", "المسلم أخو المسلم، لا يظلمه ولا يخذله، ولا يحقره. التقوى هاهنا -ويشير إلى صدره-.", "A Muslim is the brother of a Muslim: he does not wrong him, forsake him, or despise him.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(471, "صحيح البخاري", "الصدق والبيان في البيع", "2079", "البيعان بالخيار ما لم يتفرقا، فإن صدقا وبينا بورك لهما في بيعهما، وإن كتما وكذبا محقت بركة بيعهما.", "The buyer and seller have option until they separate; if honest, their trade is blessed.", "عن حكيم بن حزام رضي الله عنه"),
        HadithItem(472, "صحيح مسلم", "إمهال المعسر والوضع عنه", "3006", "من أنظر معسراً أو وضع عنه، أظله الله في ظله يوم لا ظل إلا ظله.", "Whoever gives respite to a debtor in hardship or waives it, Allah will shade him.", "عن أبي اليسر رضي الله عنه"),
        HadithItem(473, "صحيح البخاري", "تجاوز الله عن المتجاوزين", "2078", "كان رجل يداين الناس وكان يقول لفتاه: إذا أتيت معسراً فتجاوز عنه لعل الله أن يتجاوز عنا، فلقي الله فتجاوز عنه.", "A merchant used to overlook debtors' hardship; when he met Allah, He overlooked his sins.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(474, "سنن الترمذي", "تعلق نفس المؤمن بالدين", "1078", "نفس المؤمن معلقة بدينه حتى يُقضى عنه.", "The soul of the believer is suspended by his debt until it is paid off.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(475, "صحيح البخاري", "تحريم مطل الغني", "2287", "مطل الغني ظلم، وإذا أُتبع أحدكم على مليء فليتبع.", "Delaying payment of a debt by a wealthy person is injustice.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(476, "صحيح البخاري", "نية أداء أموال الناس", "2387", "من أخذ أموال الناس يريد أداءها أدى الله عنه، ومن أخذ يريد إتلافها أتلفه الله.", "Whoever takes people's money intending to pay back, Allah will fulfill it for him.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(477, "شعب الإيمان", "إتقان العمل والمهنة", "4929", "إن الله يحب إذا عمل أحدكم عملاً أن يتقنه.", "Allah loves that when one of you performs a task, he does it with excellence.", "عن عائشة رضي الله عنها"),
        HadithItem(478, "صحيح مسلم", "كتابة الإحسان في كل شيء", "1955", "إن الله كتب الإحسان على كل شيء، فإذا قتلتم فأحسنوا القتلة، وإذا ذبحتم فأحسنوا الذبحة.", "Allah has prescribed excellence in all things.", "عن شداد بن أوس رضي الله عنه"),
        HadithItem(479, "صحيح البخاري", "اليد العليا والبدء بالعيال", "1427", "اليد العليا خير من اليد السفلى، وابدأ بمن تعول، وخير الصدقة عن ظهر غنى.", "The upper hand [giving] is better than the lower hand [receiving], and start with dependents.", "عن حكيم بن حزام رضي الله عنه"),
        HadithItem(480, "مسند أحمد", "أفضل الكسب بالنصيحة", "8422", "خير الكسب كسب يدي العامل إذا نصح.", "The best of earnings is the gain of a worker's hand when he acts sincerely.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(481, "سنن الترمذي", "الإكثار من ذكر الموت", "2307", "أكثروا ذكر هادم اللذات: الموت.", "Remember frequently the destroyer of pleasures: death.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(482, "سنن الترمذي", "الكَيِّس من دان نفسه", "2459", "الكَيِّسُ مَنْ دَانَ نَفْسَهُ وَعَمِلَ لِمَا بَعْدَ الْمَوْتِ، وَالْعَاجِزُ مَنْ أَتْباعَ نَفْسَهُ هَوَاهَا وَتَمَنَّى عَلَى اللهِ.", "The wise one is he who calls himself to account and works for what comes after death.", "عن شداد بن أوس رضي الله عنه"),
        HadithItem(483, "صحيح البخاري", "ما يتبع الميت بعد موته", "6514", "يتبع الميت ثلاثة: فيرجع اثنان ويبقى واحد؛ يتبع أهله وماله وعمله، فيرجع أهله وماله ويبقى عمله.", "Three follow the deceased: family, wealth, deeds. Two return and deeds remain.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(484, "صحيح مسلم", "تلقين المحتضر الشهادة", "916", "لقنوا موتاكم لا إله إلا الله.", "Prompt your dying ones to say: La ilaha illallah.", "عن أبي سعيد الخدري رضي الله عنه"),
        HadithItem(485, "سنن أبي داود", "فضل آخر الكلام بالشهادة", "3116", "من كان آخر كلامه لا إله إلا الله دخل الجنة.", "He whose last words are 'La ilaha illallah' will enter Paradise.", "عن معاذ بن جبل رضي الله عنه"),
        HadithItem(486, "صحيح مسلم", "حسن الظن بالله عند الموت", "2877", "لا يموتن أحدكم إلا وهو يحسن الظن بالله عز وجل.", "None of you should die except expecting the best from Allah Almighty.", "عن جابر بن عبد الله رضي الله عنهما"),
        HadithItem(487, "صحيح البخاري", "محبة لقاء الله تعالى", "6507", "من أحب لقاء الله أحب الله لقاءه، ومن كره لقاء الله كره الله لقاءه.", "Whoever loves to meet Allah, Allah loves to meet him.", "عن عبادة بن الصامت رضي الله عنه"),
        HadithItem(488, "سنن الترمذي", "التوفيق للعمل الصالح قبل الموت", "2142", "إذا أراد الله بعبد خيراً استعمله. قيل: كيف يستعمله؟ قال: يوفقه لعمل صالح قبل الموت.", "When Allah wills good for a servant, He guides him to perform righteous deeds before death.", "عن أنس بن مالك رضي الله عنه"),
        HadithItem(489, "صحيح مسلم", "البعث على حالة الموت", "2878", "يُبعث كل عبد على ما مات عليه.", "Every servant will be resurrected upon that which he died upon.", "عن جابر بن عبد الله رضي الله عنهما"),
        HadithItem(490, "سنن الترمذي", "القبر أول منازل الآخرة", "2308", "القبر أول منزل من منازل الآخرة، فإن نجا منه فما بعده أيسر منه، وإن لم ينجُ منه فما بعده أشد منه.", "The grave is the first stage of the Hereafter; if one escapes it, what follows is easier.", "عن عثمان بن عفان رضي الله عنه"),
        HadithItem(491, "صحيح مسلم", "زيارة القبور للتذكرة", "976", "زوروا القبور فإنها تذكركم الآخرة.", "Visit the graves, for they remind you of the Hereafter.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(492, "صحيح البخاري", "الاستعاذة من عذاب القبر والفتن", "1377", "اللهم إني أعوذ بك من عذاب القبر، ومن عذاب جهنم، ومن فتنة المحيا والممات، ومن شر فتنة المسيح الدجال.", "O Allah, I seek refuge in You from the punishment of the grave and Hellfire...", "عن أبي هريرة رضي الله عنه"),
        HadithItem(493, "صحيح البخاري", "فضل صلاة الجماعة", "645", "صلاة الجماعة تفضل صلاة الفذ بسبع وعشرين درجة.", "Praying in congregation is twenty-seven times superior to praying alone.", "عن عبد الله بن عمر رضي الله عنهما"),
        HadithItem(494, "صحيح البخاري", "أجر بناء المساجد", "450", "من بنى مسجداً يبتغي به وجه الله بنى الله له مثله في الجنة.", "Whoever builds a mosque seeking Allah's pleasure, Allah will build for him a house in Paradise.", "عن عثمان بن عفان رضي الله عنه"),
        HadithItem(495, "صحيح مسلم", "قيام الليل بصلاة العشاء والصبح", "656", "من صلى العشاء في جماعة فكأنما قام نصف الليل، ومن صلى الصبح في جماعة فكأنما صلى الليل كله.", "Whoever prays Isha in congregation, it is as if he prayed half the night; and Fajر the whole night.", "عن عثمان بن عفان رضي الله عنه"),
        HadithItem(496, "سنن أبي داود", "بشارة المشائين في الظلم", "561", "بشر المشائين في الظلم إلى المساجد بالنور التام يوم القيامة.", "Give glad tidings to those who walk to mosques in darkness of complete light on Judgment Day.", "عن بريدة الأسلمي رضي الله عنه"),
        HadithItem(497, "صحيح مسلم", "خطوات المشي إلى المساجد", "666", "من تطهر في بيته ثم مضى إلى بيت من بيوت الله ليقضي فريضة كانت خطوتاه إحداهما تحط خطيئة والأخرى ترفع درجة.", "Whoever purifies himself at home and walks to the mosque, his steps wipe sins and elevate ranks.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(498, "صحيح مسلم", "أقرب ما يكون العبد في السجود", "482", "أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء.", "The closest a servant comes to his Lord is while he is in prostration, so supplicate abundantly.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(499, "صحيح مسلم", "إقامة الصلاة المكتوبة", "710", "إذا أقيمت الصلاة فلا صلاة إلا المكتوبة.", "When the prayer is established, there is no prayer except the prescribed one.", "عن أبي هريرة رضي الله عنه"),
        HadithItem(500, "صحيح البخاري", "خاتمة الدعاء بالخيرين والحمد", "6389", "ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار، والحمد لله رب العالمين.", "Our Lord, give us in this world good and in the Hereafter good and protect us from the Fire.", "عن أنس بن مالك رضي الله عنه"),
    )

    val HADITHS_400: List<HadithItem> get() = HADITHS_500
    val HADITHS_200: List<HadithItem> get() = HADITHS_500
}
